  ('air-and-style--2019', 'air-and-style--2019', 'Air + Style Beijing 2019', 'air-and-style', 2019, '2019-12', NULL, 'contest', 'Run as an FIS big air World Cup (FIS news item dated 15 December 2019). German Wikipedia calls the 2019 Beijing event the 25th and most recent edition of Air & Style. Exact dates and venue not confirmed in a page I opened.', 'unverified', 'held', NULL, 'month', NULL, 'Beijing', 'China', ARRAY['big-air']::text[], ARRAY['https://www.fis-ski.com/snowboard-park-and-pipe/news/2019-20/air-style-beijing-big-air-world-cup-2019-20','https://de.wikipedia.org/wiki/Air_%26_Style']::text[], 'likely'),
  ('argentina-snowboard-tour--2012', 'argentina-snowboard-tour--2012', 'Argentina Snowboard Tour 2012', 'argentina-snowboard-tour', 2012, '2012-05', '2012-08', 'contest', 'Five events between May and August 2012: urban big airs in Buenos Aires (one of them invitational) plus stops at Cerro Chapelco, Cerro Bayo and Cerro Catedral. All but the invitational open to any rider regardless of nationality or level.', 'unverified', 'held', NULL, 'month', NULL, NULL, 'Argentina', ARRAY['big-air','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-argentina-snowboard-tour-ast/']::text[], 'likely'),
  ('argentina-snowboard-tour--2014', 'argentina-snowboard-tour--2014', 'Argentina Snowboard Tour 2014', 'argentina-snowboard-tour', 2014, '2014', NULL, 'contest', 'Third tour stop was the Snow Travel South America Snowboard Challenge slopestyle at La Hoya on 20 August 2014, the second time La Hoya hosted it and the final stop of the season for Brazilian riders. Other 2014 stops not listed in the source. Related Argentine events reported the same season: Rip Curl Grom Winter Search and the ALIVE and KICKING Rip Curl Pro (23 Aug) at Cerro Catedral, Bariloche, and the DC Slopestyle Pro at Cerro Chapelco (5 Aug).', 'unverified', 'held', NULL, 'year', NULL, NULL, 'Argentina', ARRAY['slopestyle','big-air']::text[], ARRAY['https://www.worldsnowboardfederation.org/third-tour-stop-argentina-snowboard-tour-2014/','https://www.worldsnowboardfederation.org/?s=Argentina']::text[], 'likely'),
  ('audi-nines--2014', 'audi-nines--2014', 'Nine Knights & Nine Queens 2014', 'audi-nines', 2014, '2014', NULL, 'contest', 'First edition to combine the men''s and women''s events, and the first with snowboarders on the roster.', 'unverified', 'held', NULL, 'year', 'Livigno', 'Livigno', 'Italy', ARRAY['big-air','hip','other']::text[], ARRAY['https://www.downdays.eu/articles/audi-nines-retrospective/']::text[], 'likely'),
