  ('audi-snowboard-series--2013', 'audi-snowboard-series--2013', 'Audi Snowboard Series 2013/14', 'audi-snowboard-series', 2013, '2013', NULL, 'contest', 'More than 30 events across Switzerland in freestyle, boardercross and race. Named stops include a 3-Star World Snowboard Tour contest at Laax and European Cups at Davos, Lenzerheide and Lenk; the Swiss Championships in all three disciplines close the season, with the freestyle championships at Corvatsch on 11-12 April 2014.', 'verified', 'held', NULL, 'year', NULL, NULL, 'Switzerland', ARRAY['slopestyle','halfpipe','boardercross','other']::text[], ARRAY['https://www.worldsnowboardfederation.org/audi-snowboard-series/']::text[], 'verified'),
