  ('baldy-banked-slalom--2026', 'baldy-banked-slalom--2026', '2026 Baldy Banked Slalom', 'baldy-banked-slalom', 2026, '2026-03-07', '2026-03-07', 'contest', 'Described by the source as ''now in its 14th year''. Dates from a third-party events roundup.', 'unverified', 'held', NULL, 'day', 'Sun Valley Resort', 'Sun Valley, Idaho', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('bc-snowboard-provincial-series--2025', 'bc-snowboard-provincial-series--2025', '2025 BC Snowboard Provincial Series', 'bc-snowboard-provincial-series', 2025, '2025-01-11', '2025-03-19', 'contest', 'Season stops per BC Snowboard''s results archive: Whistler Blackcomb slopestyle 11-12 January; Big White SBX 18-19 January; Big White slopestyle 25-26 January; Silver Star slopestyle 22-23 February; Sun Peaks slopestyle 17 March; Sun Peaks SBX 19 March. The Neil Edgeworth Memorial Banked Slalom (28-30 March) and the Sun Peaks Speed Nation SBX Tour stop (4-5 January) appear in the same archive but are separate events.', 'verified', 'held', NULL, 'day', NULL, NULL, 'Canada', ARRAY['slopestyle','boardercross']::text[], ARRAY['https://www.bcsnowboard.com/2025-event-results/']::text[], 'verified'),
  ('big-white-para-snowboard-world-cup--2017', 'big-white-para-snowboard-world-cup--2017', '2017 World Para Snowboard Championships', 'big-white-para-snowboard-world-cup', 2017, '2017-02-01', '2017-02-08', 'contest', 'Over 100 athletes from 25 countries. Snowboardcross contested 4 February, banked slalom 7 February, in SB-LL1, SB-LL2 and SB-UL classes for men and women. Dry-land work was done in advance to rebuild the start section and first turn.', 'verified', 'held', NULL, 'day', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['boardercross','banked-slalom']::text[], ARRAY['https://www.canadasnowboard.ca/en/news/?id=1147']::text[], 'verified'),
