  ('big-white-para-snowboard-world-cup--2019', 'big-white-para-snowboard-world-cup--2019', '2019 World Para Snowboard World Cup Big White', 'big-white-para-snowboard-world-cup', 2019, '2019-02-03', '2019-02-08', 'contest', 'Canada Snowboard announced this as para snowboard''s seventh consecutive year at Big White.', 'verified', 'held', NULL, 'day', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['boardercross','banked-slalom']::text[], ARRAY['https://www.canadasnowboard.ca/en/news/?id=1259','https://www.canadasnowboard.ca/en/news/?id=1258']::text[], 'verified'),
  ('big-white-para-snowboard-world-cup--2025', 'big-white-para-snowboard-world-cup--2025', 'FIS Para Snowboard World Championships 2025', 'big-white-para-snowboard-world-cup', 2025, '2025-03-04', '2025-03-10', 'contest', 'Banked slalom course had 23 banks. Included the first team event in para snowboard World Championship history.', 'verified', 'held', NULL, 'day', 'TELUS Park, Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['boardercross','banked-slalom','team']::text[], ARRAY['https://www.bigwhite.com/explore-big-white/blog/mountain-news/fis-pswc-25']::text[], 'verified'),
