  ('bomb-hole-cup--2026', 'bomb-hole-cup--2026', '5th Annual Bomb Hole Cup', 'bomb-hole-cup', 2026, '2026', NULL, 'contest', 'Day one banked slalom, day two open-jam park showdown. Held in April 2026; exact dates not stated on the resort page, which announces April 3-4, 2027 for the next edition.', 'unverified', 'held', NULL, 'year', 'Brighton Resort', 'Brighton, Utah', 'USA', ARRAY['banked-slalom','jib']::text[], ARRAY['https://www.brightonresort.com/events/the-bomb-hole-cup','https://www.snowboard.international/features/north-america-snowboard-events-2025-26/']::text[], 'likely'),
  ('bomber-banked-slalom--2026', 'bomber-banked-slalom--2026', '13th Annual Bomber Banked Slalom', 'bomber-banked-slalom', 2026, '2026-03-28', '2026-03-29', 'contest', 'One run per day over two days; 14 divisions; field capped at 250 snowboarders. Course on Katsuk at the summit off Chair 2.', 'unverified', 'held', NULL, 'day', 'Mission Ridge Ski and Board Resort', 'Wenatchee, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://www.missionridge.com/event/bomber-banked-slalom/']::text[], 'likely'),
