  ('burton-australian-open--2008', 'burton-australian-open--2008', '2008 Burton Australian Open', 'burton-australian-open', 2008, '2008-09-02', '2008-09-06', 'contest', 'Second stop of the 2008/09 Burton Global Open Series, as announced in the series calendar. Disciplines not stated in the announcement. [QA-flagged: dates and venue are from a pre-season calendar, so the event is confirmed as scheduled rather than as held.]', 'unverified', 'held', NULL, 'day', 'Perisher Blue', NULL, 'Australia', NULL, ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'likely'),
  ('burton-canadian-open--2009', 'burton-canadian-open--2009', '2009 Burton Canadian Open', 'burton-canadian-open', 2009, '2009', NULL, 'contest', 'Rated Swatch TTR 5Star. Mikkel Bang and Silvia Mittermueller won the slopestyle, reported by Onboard on 2009-02-09. Unresolved: the 2008/09 Burton Global Open Series calendar announced the Burton Canadian Open for 2008-12-01 to 2008-12-07 at the same venue, so either the edition moved to February 2009 or there were two runnings. Only one edition row is recorded here.', 'unverified', 'held', NULL, 'year', 'Canada Olympic Park', 'Calgary', 'Canada', ARRAY['slopestyle']::text[], ARRAY['https://onboardmag.com/news/snowboarding-events/burton-canadian-open-slopestyle.html','https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'likely'),
  ('burton-canadian-open--2010', 'burton-canadian-open--2010', '2010 Burton Canadian Open', 'burton-canadian-open', 2010, '2010-02-01', '2010-02-07', 'contest', '5Star TTR event; men''s and women''s slopestyle and halfpipe. Dates from the TTR World Snowboard Tour registration listing.', 'verified', 'held', NULL, 'day', 'Canada Olympic Park', 'Calgary', 'Canada', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/registration-open-for-ttr-world-snowboard-tour-events/']::text[], 'verified'),
  ('burton-european-open--1999', 'burton-european-open--1999', '1999 Burton European Open', 'burton-european-open', 1999, '1999', NULL, 'contest', 'Reported as the first Burton European Open, with the halfpipe at Axamer Lizum and the slopestyle at Seegrube in the Innsbruck area. Natasza Zurek won the halfpipe. Note that later edition numbering used by the organisers and the World Snowboard Federation (2011 = 12th annual, 2012 = 13th annual) counts the first edition as 2000, so the year of this first edition is disputed.', 'unverified', 'held', NULL, 'year', 'Axamer Lizum / Seegrube', 'Innsbruck', 'Austria', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html']::text[], 'likely'),
  ('burton-european-open--2001', 'burton-european-open--2001', '2001 Burton European Open', 'burton-european-open', 2001, '2001', NULL, 'contest', 'The only year alpine snowboarders competed alongside the freestyle disciplines.', 'unverified', 'held', NULL, 'year', 'Fieberbrunn', 'Fieberbrunn', 'Austria', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html']::text[], 'likely'),
  ('burton-european-open--2002', 'burton-european-open--2002', '2002 Burton European Open', 'burton-european-open', 2002, '2002', NULL, 'contest', 'Cooler''s 2009 retrospective places the Burton European Open at Livigno, Italy for 2002-2004. Exact dates not sourced. Natasza Zurek won the halfpipe at Livigno in 2003.', 'unverified', 'held', NULL, 'year', 'Livigno', 'Livigno', 'Italy', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html']::text[], 'likely'),
  ('burton-european-open--2003', 'burton-european-open--2003', '2003 Burton European Open', 'burton-european-open', 2003, '2003-01-18', '2003-01-25', 'contest', 'Cooler''s 2009 retrospective places the Burton European Open at Livigno, Italy for 2002-2004. Exact dates not sourced. Natasza Zurek won the halfpipe at Livigno in 2003. [v0.3 archive: Open Championships of Snowboarding 2003 calendar: "Jan 18 - 25, 2003 Livigno, IT".] [v0.3 archive: Open Championships of Snowboarding 2003 calendar: "Jan 18 - 25, 2003 Livigno, IT".]', 'unverified', 'held', NULL, 'day', 'Livigno', 'Livigno', 'Italy', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://web.archive.org/web/20030205093000/http://www.opensnowboarding.com/']::text[], 'likely'),
  ('burton-european-open--2004', 'burton-european-open--2004', '2004 Burton European Open', 'burton-european-open', 2004, '2004-01-10', '2004-01-17', 'contest', 'Cooler''s 2009 retrospective places the Burton European Open at Livigno, Italy for 2002-2004. Exact dates not sourced. Natasza Zurek won the halfpipe at Livigno in 2003. [v0.3 archive: 2004 Open Championships of Snowboarding calendar: "Burton European Open January 10-17, 2004 Livigno, Italy".] [v0.3 archive: 2004 Open Championships of Snowboarding calendar: "Burton European Open January 10-17, 2004 Livigno, Italy".]', 'unverified', 'held', NULL, 'day', 'Livigno', 'Livigno', 'Italy', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://web.archive.org/web/20040205215129/http://www.opensnowboarding.com/']::text[], 'likely'),
  ('burton-european-open--2005', 'burton-european-open--2005', '2005 Burton European Open', 'burton-european-open', 2005, '2005-01-15', '2005-01-22', 'contest', 'Laax became the permanent home of the Burton European Open from 2005. Natasza Zurek won slopestyle in both 2005 and 2006. Exact dates not sourced. [v0.3 archive: Open Championships of Snowboarding calendar: "Burton European Open Jan. 15-22, 2005 Laax, Switzerland".] [v0.3 archive: Open Championships of Snowboarding calendar: "Burton European Open Jan. 15-22, 2005 Laax, Switzerland".]', 'unverified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://web.archive.org/web/20050113043806/http://www.opensnowboarding.com/']::text[], 'likely'),
  ('burton-european-open--2006', 'burton-european-open--2006', '2006 Burton European Open', 'burton-european-open', 2006, '2006-01-14', '2006-01-21', 'contest', 'Laax became the permanent home of the Burton European Open from 2005. Natasza Zurek won slopestyle in both 2005 and 2006. Exact dates not sourced. [v0.3 archive: Open Championships of Snowboarding calendar: "Burton European Open Jan. 14-21, 2006 Laax, Switzerland".] [v0.3 archive: Open Championships of Snowboarding calendar: "Burton European Open Jan. 14-21, 2006 Laax, Switzerland".]', 'unverified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://web.archive.org/web/20060213052702/http://www.opensnowboarding.com/']::text[], 'likely'),
  ('burton-european-open--2007', 'burton-european-open--2007', '2007 Burton European Open', 'burton-european-open', 2007, '2007-01-20', '2007-01-27', 'contest', 'The 8th Burton European Open, and a 6Star event on the 2006/07 TTR World Snowboard Tour. The BEO''s own history page, written for the 2007 event, says "The Burton European Open goes into his 8th edition in 2007".', 'verified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', NULL, ARRAY['https://web.archive.org/web/20061104145301/http://www.opensnowboarding.com/','https://web.archive.org/web/20070817202135/http://www.burtoneuropeanopen.com/History.aspx']::text[], 'verified'),
  ('burton-european-open--2008', 'burton-european-open--2008', '2008 Burton European Open', 'burton-european-open', 2008, '2008-01-11', '2008-01-18', 'contest', 'The fourth 6Star stop of the Swatch TTR World Snowboard Tour season and the first event that season to host both men''s and women''s fields, with 1000 ranking points per discipline.', 'verified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/burton-european-open-2008/','https://www.worldsnowboardfederation.org/burton-european-open-08-results/']::text[], 'verified'),
  ('burton-european-open--2009', 'burton-european-open--2009', '2009 Burton European Open', 'burton-european-open', 2009, '2009-01-09', '2009-01-16', 'contest', 'Marked by the organisers as the tenth-anniversary edition. USD 125,000 prize pool; all 400 open registration spots filled within days. Part of the 2008/09 Burton Global Open Series.', 'verified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'verified'),
  ('burton-european-open--2010', 'burton-european-open--2010', '2010 Burton European Open', 'burton-european-open', 2010, '2010-01-09', '2010-01-16', 'contest', '6Star TTR for the open fields and 4Star for the juniors. Sources disagree on the dates: the TTR registration listing gives 2010-01-09 to 2010-01-16 and the World Snowboard Federation event write-up gives 2010-01-10 to 2010-01-16.', 'unverified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/registration-open-for-ttr-world-snowboard-tour-events/','https://www.worldsnowboardfederation.org/the-6star-burton-european-open-bring-the-circus-to-the-swatch-ttr-tour/']::text[], 'likely'),
  ('burton-european-open--2011', 'burton-european-open--2011', '12th Annual Burton European Open (2011)', 'burton-european-open', 2011, '2011-01-08', '2011-01-15', 'contest', 'Eight-day 6Star TTR event with over 300 riders and a USD 125,000 prize purse. Peetu Piiroinen and Kelly Clark won the halfpipe.', 'verified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/12th-annual-6star-burton-european-open-attracts-top-athletes/','https://whitelines.com/events/burton-european-open']::text[], 'verified'),
  ('burton-european-open--2012', 'burton-european-open--2012', '13th Annual Burton European Open (2012)', 'burton-european-open', 2012, '2012-02-25', '2012-03-03', 'contest', 'Men''s, women''s and junior fields in slopestyle and halfpipe. Points counted toward both the TTR and the Burton Global Open Series rankings. The only documented year the BEO ran in late February rather than January.', 'verified', 'held', NULL, 'day', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://snowboardmag.com/stories/2012-burton-european-open-confirms-top-snowboarders-live-acts','https://www.worldsnowboardfederation.org/world-champions-win-the-burton-european-open-halfpipe-contest/']::text[], 'verified'),
  ('burton-european-open--2014', 'burton-european-open--2014', '2014 Burton European Open', 'burton-european-open', 2014, '2014', NULL, 'contest', 'Presented by MINI. Halfpipe semi-finals on the LAAX superpipe 2014-01-16 with finals 2014-01-17; Iouri Podladtchikov and Ursina Haller won the halfpipe. Full event dates not sourced.', 'unverified', 'held', NULL, 'year', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/burton-european-open-2014-presented-by-mini/','https://www.worldsnowboardfederation.org/ursina-haller-and-iouri-podladtchikov-win-the-6-star-burton-european-open-halfpi/']::text[], 'likely'),
  ('burton-european-open--2015', 'burton-european-open--2015', '2015 Burton European Open', 'burton-european-open', 2015, '2015', NULL, 'contest', 'Final Burton European Open. First event of the WST Pro Series. Slopestyle finals 2015-02-01, won by Stale Sandbech and Christy Prior; Iouri Podladtchikov and Kelly Clark won the halfpipe. Full event dates not sourced.', 'unverified', 'held', NULL, 'year', 'Laax', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/stale-sandbech-christy-prior-win-slopestyle-finals-burton-european-open/','https://whitelines.com/events/burton-european-open']::text[], 'likely'),
  ('burton-global-open-series--2008', 'burton-global-open-series--2008', '2008/09 Burton Global Open Series', 'burton-global-open-series', 2008, '2008-07-29', '2009-03-22', 'contest', 'Six-stop season, announced as: Burton New Zealand Open, Snow Park NZ, 2008-07-29 to 2008-08-02; Burton Australian Open, Perisher Blue, 2008-09-02 to 2008-09-06; Burton Canadian Open, Canada Olympic Park, 2008-12-01 to 2008-12-07; Burton European Open, Laax, 2009-01-09 to 2009-01-16; Nissan X-Trail Nippon Open, ALTS Bandai, 2009-02-24 to 2009-03-01; Burton US Open, Stratton Mountain, 2009-03-16 to 2009-03-22. Year recorded as 2008, the calendar year the season opened; end date is the announced close of the US Open.', 'verified', 'held', NULL, 'day', NULL, NULL, 'multiple', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'verified'),
  ('burton-global-open-series--2010', 'burton-global-open-series--2010', '2010/11 Burton Global Open Series', 'burton-global-open-series', 2010, '2010-08-10', NULL, 'contest', 'The 2010 Burton New Zealand Open at Cardrona, 2010-08-10 to 2010-08-14, was reported as the opening event of the 2010/11 Burton Global Open Series. The full stop list and closing date for this season were not sourced. Kelly Clark won a Burton Global Open Series championship at the March 2011 US Open.', 'unverified', 'held', NULL, 'day', NULL, NULL, 'multiple', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.snowboarder.com/news/2010-burton-new-zealand-open-gears-up','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/']::text[], 'likely'),
