  ('burton-new-zealand-open--2006', 'burton-new-zealand-open--2006', '2006 Burton New Zealand Open', 'burton-new-zealand-open', 2006, '2006-08-03', '2006-08-05', 'contest', 'NZD 50,000 prize pool.', 'unverified', 'held', NULL, 'day', 'Snow Park NZ', 'Wanaka', 'New Zealand', ARRAY['halfpipe','slopestyle','quarterpipe']::text[], ARRAY['https://info.scoop.co.nz/Burton_NZ_Open']::text[], 'likely'),
