  ('fis-snowboard-world-cup--2026', 'fis-snowboard-world-cup--2026', '2025/26 FIS Snowboard World Cup season', 'fis-snowboard-world-cup', 2026, '2025-11-27', '2026-03-29', 'contest', 'Olympic season (Milano-Cortina 2026); most recent completed season as of September 2026. Opened at Secret Garden (CHN) and closed at Mt. St. Anne (CAN); the FIS cup-standings page is headed ''After Men''s Snowboard Cross Mt. St. Anne (CAN) 28-03-2026 (8/8)''. FIS calendar lists 40 World Cup event weekends for this season. Counts are of calendar rows (each row can carry several races) and include any events later cancelled; they have not been reconciled against results actually run. Row represents the whole season, keyed to the season end year, not a single stop.', 'verified', 'held', NULL, 'day', NULL, NULL, 'multiple', NULL, ARRAY['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2026&categorycode=WC']::text[], 'verified'),
  ('focus-banked-slalom--2026', 'focus-banked-slalom--2026', '2026 Focus Banked Slalom', 'focus-banked-slalom', 2026, '2026-03-01', '2026-03-01', 'contest', 'Described by the source as ''now in its 19th year''. Dates from a third-party events roundup.', 'unverified', 'held', NULL, 'day', 'Tyrol Basin', 'Mount Horeb, Wisconsin', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('freestyle-ch--2004', 'freestyle-ch--2004', 'freestyle.ch 2004', 'freestyle-ch', 2004, '2004', NULL, 'contest', 'Admission was made payable from 2005 onward, partly in response to safety and crowd management.', 'unverified', 'held', 'Abandoned after the first day when the big air snow ramp collapsed. No injuries were reported.', 'year', 'Landiwiese', 'Zurich', 'Switzerland', ARRAY['big-air']::text[], ARRAY['https://de.wikipedia.org/wiki/Freestyle.ch']::text[], 'likely'),
  ('gravity-games-winter--2000', 'gravity-games-winter--2000', 'Winter Gravity Games I (2000)', 'gravity-games-winter', 2000, '2000', NULL, 'contest', 'Only winter edition of the Gravity Games. Held in heavy snowfall. Snowboard superpipe, big air and boarder X plus skier X. No dates found in any source opened.', 'unverified', 'held', NULL, 'year', 'Mammoth Mountain', 'Mammoth Lakes, California', 'USA', ARRAY['superpipe','big-air','boardercross']::text[], ARRAY['https://en.wikipedia.org/wiki/Gravity_Games']::text[], 'likely'),
  ('halo-halo-timberline--2026', 'halo-halo-timberline--2026', '2026 Halo-Halo', 'halo-halo-timberline', 2026, '2026-07-10', '2026-07-12', 'contest', 'Dates from a third-party events roundup, not from the organiser.', 'unverified', 'held', NULL, 'day', 'Timberline Lodge and Ski Area', 'Mount Hood, Oregon', 'USA', NULL, ARRAY['https://www.snowboard.international/features/north-america-snowboard-events-2025-26/']::text[], 'likely'),
  ('holy-oly-revival--2007', 'holy-oly-revival--2007', '4th Annual Holy Oly Revival', 'holy-oly-revival', 2007, '2007-02', '2007-02', 'contest', 'Announced by Lib Tech on 14 February 2007 as the fourth annual Holy Oly Revival. Exact contest dates not given in the source.', 'unverified', 'held', NULL, 'month', 'The Summit at Snoqualmie', 'Snoqualmie Pass, Washington', 'USA', ARRAY['quarterpipe','jib']::text[], ARRAY['https://www.lib-tech.com/blog/2007/02/14/holy-crap-it%E2%80%99s-the-fourth-annual-holy-oly-revival/']::text[], 'likely'),
  ('holy-oly-revival--2010', 'holy-oly-revival--2010', '7th Annual Holy Oly Revival', 'holy-oly-revival', 2010, '2010-02', '2010-02', 'contest', 'Covered by Snowboarder on 21 February 2010 as the 7th annual, and by the GNU and Lib Tech blogs on 24 February 2010. Exact contest dates not given in the sources.', 'unverified', 'held', NULL, 'month', 'The Summit at Snoqualmie', 'Snoqualmie Pass, Washington', 'USA', ARRAY['quarterpipe','jib']::text[], ARRAY['https://www.snowboarder.com/news/7th-annual-holy-oly-the-olympic-hangover-cure','https://www.gnu.com/blog/2010/02/24/holy-oly-you-can%E2%80%99t-spell-olympics-without-oly/']::text[], 'likely'),
  ('hot-dawgz-and-hand-rails--2012', 'hot-dawgz-and-hand-rails--2012', '9th Annual Hot Dawgz & Hand Rails', 'hot-dawgz-and-hand-rails', 2012, '2012-09-22', '2012-09-22', 'contest', 'Presented by Red Bull; 40 pro snowboarders, jam format, 130 tons of man-made snow, starting 2pm.', 'verified', 'held', NULL, 'day', 'Bear Mountain', 'Big Bear Lake, California', 'USA', ARRAY['rail-jam','jib']::text[], ARRAY['https://www.firsttracksonline.com/2012/09/07/hot-dawgz-and-hand-rails-pre-season-rail-jam-returns-to-bear-mountain/']::text[], 'verified'),
  ('hot-dawgz-and-hand-rails--2013', 'hot-dawgz-and-hand-rails--2013', '10th Anniversary Hot Dawgz & Hand Rails', 'hot-dawgz-and-hand-rails', 2013, '2013-09-22', NULL, 'contest', 'Men''s winner Tommy Gesme took a $10,000 first prize; Dillon Ojo 2nd, Jordan Small 3rd. Melissa Evans won the women''s event, described as her fourth win at the contest. Jaeger Bailey took Best Trick. Not in the wave 1 edition list; results not recorded here because edition_ids must come from the input file.', 'verified', 'held', NULL, 'day', 'Bear Mountain', 'Big Bear Lake, California', 'USA', ARRAY['rail-jam','jib']::text[], ARRAY['https://www.snowboarder.com/news/tommy-gesme-wins-hot-dawgz-hand-rails-2013']::text[], 'verified'),
  ('isf-snowboard-world-championships--1993', 'isf-snowboard-world-championships--1993', '1993 ISF World Championships', 'isf-snowboard-world-championships', 1993, '1993', NULL, 'contest', 'First ISF World Championships. Snowboarder magazine''s 1990s history timeline records Kevin Delaney (USA) and Michele Taggart (USA) as the combined title winners. No dates or event-by-event programme found. Terje Haakonsen is separately credited with ISF halfpipe world titles in 1993, 1995 and 1997, which suggests a biennial odd-year cycle, but no edition list has been located.', 'unverified', 'held', NULL, 'year', 'Ischgl', 'Ischgl', 'Austria', NULL, ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[], 'likely'),
  ('isf-world-championships--1993', 'isf-world-championships--1993', '1993 ISF Snowboard World Championships', 'isf-world-championships', 1993, '1993-01', '1993-01', 'contest', 'First ISF world championships. Snowboarder/TransWorld 1990s timeline gives January 1993 at Ischgl, Austria and says Kevin Delaney and Michele Taggart won the combined titles; carvers.it repeats the same. German Wikipedia lists slalom, combined, halfpipe and giant slalom as the 1993 disciplines. Only the combined winners are recorded; no full podium found.', 'unverified', 'held', NULL, 'month', NULL, 'Ischgl', 'Austria', ARRAY['halfpipe','giant-slalom','slalom','other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.carvers.it/storia-inglese/','https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaft']::text[], 'likely'),
  ('isf-world-snowboarding-championships--1993', 'isf-world-snowboarding-championships--1993', '1993 ISF World Championships', 'isf-world-snowboarding-championships', 1993, '1993', NULL, 'contest', 'First official ISF Snowboard World Championships. Combined titles were awarded.', 'unverified', 'held', NULL, 'year', 'Ischgl', 'Ischgl, Tirol', 'Austria', ARRAY['other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[], 'likely'),
  ('isf-world-snowboarding-championships--2000', 'isf-world-snowboarding-championships--2000', 'Motorola ISF World Championships 1999/2000 - halfpipe final', 'isf-world-snowboarding-championships', 2000, '2000-04-08', '2000-04-08', 'contest', 'Halfpipe world championship decider of the season-long Motorola ISF World Pro Tour, run in front of roughly 5,000 spectators, with alpine finals alongside. The tour then moved to Laax for the boardercross. Records the title as decided over a season rather than at a single championship meeting.', 'verified', 'held', NULL, 'day', 'Jakobshorn, Davos', 'Davos', 'Switzerland', ARRAY['halfpipe']::text[], ARRAY['https://www.sportcal.com/pressreleases/the-motorola-isf-world-championships-1999-2000-halfpipe-davos-sui/']::text[], 'verified'),
  ('jla-mammoth-banked-slalom--2026', 'jla-mammoth-banked-slalom--2026', '2026 JLA Mammoth Banked Slalom', 'jla-mammoth-banked-slalom', 2026, '2026-02-27', '2026-03-01', 'contest', 'Dates from a third-party events roundup, not from the organiser.', 'unverified', 'held', NULL, 'day', 'Mammoth Mountain', 'Mammoth Lakes, California', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('jsba-all-japan-snowboard-championships--2022', 'jsba-all-japan-snowboard-championships--2022', '40th JSBA All Japan Snowboard Championships', 'jsba-all-japan-snowboard-championships', 2022, '2022-03-13', '2022-03-21', 'contest', 'Both venues in Hokkaido. Riders qualified via regional and G1 events. ''Straight jump'' is the JSBA term recorded for the big air discipline.', 'verified', 'held', NULL, 'day', 'Sapporo Bankei Ski Area and Nayoro Piyashiri Ski Area', 'Sapporo and Nayoro, Hokkaido', 'Japan', ARRAY['halfpipe','big-air','slopestyle','boardercross','dual-slalom','giant-slalom']::text[], ARRAY['https://www.jsba.or.jp/ajsc_site/ajsc40/']::text[], 'verified'),
  ('jsba-all-japan-snowboard-championships--2023', 'jsba-all-japan-snowboard-championships--2023', '41st JSBA All Japan Snowboard Championships', 'jsba-all-japan-snowboard-championships', 2023, '2023-03-08', '2023-03-12', 'contest', 'Split across two host resorts. The JSBA site describes the championship as annual since 1983.', 'verified', 'held', NULL, 'day', 'Ishiuchi Maruyama Ski Resort and Tsugaike Kogen Ski Resort', 'Minamiuonuma, Niigata and Kitaazumi, Nagano', 'Japan', ARRAY['halfpipe','slopestyle','boardercross','big-air','giant-slalom','dual-slalom']::text[], ARRAY['https://www.jsba.or.jp/ajsc_site/ajsc41/']::text[], 'verified'),
  ('jsba-all-japan-snowboard-championships--2024', 'jsba-all-japan-snowboard-championships--2024', '42nd JSBA All Japan Snowboard Championships', 'jsba-all-japan-snowboard-championships', 2024, '2024', NULL, 'contest', '42nd edition; open-division champions listed on the JSBA historical champions page. Dates and venues not researched.', 'unverified', 'held', NULL, 'year', NULL, NULL, 'Japan', ARRAY['halfpipe','big-air','slopestyle','boardercross','dual-slalom','giant-slalom']::text[], ARRAY['https://www.jsba.or.jp/ajsc_site/ajsc43/champion.html']::text[], 'likely'),
  ('jsba-all-japan-snowboard-championships--2025', 'jsba-all-japan-snowboard-championships--2025', '43rd JSBA All Japan Snowboard Championships', 'jsba-all-japan-snowboard-championships', 2025, '2025-03-07', '2025-03-19', 'contest', 'Main block 7-11 March at Aizu Kogen Takatsue (Fukushima); a further competition day on 19 March at Takasu Snow Park (Gifu). The site names halfpipe (HP) and dual (DU) among the events; the full discipline list is on a separate page not opened.', 'verified', 'held', NULL, 'day', 'Aizu Kogen Takatsue Ski Resort and Takasu Snow Park', 'Minamiaizu, Fukushima and Gujo, Gifu', 'Japan', ARRAY['halfpipe','dual-slalom','other']::text[], ARRAY['https://www.jsba.or.jp/ajsc_site/ajsc43/']::text[], 'verified'),
  ('jsba-all-japan-snowboard-technical-championships--2026', 'jsba-all-japan-snowboard-technical-championships--2026', '33rd JSBA All Japan Snowboard Technical Championships', 'jsba-all-japan-snowboard-technical-championships', 2026, '2026-02-26', '2026-02-28', 'contest', 'Alpine and Freestyle categories for men and women plus a club team competition. Regional qualifiers run three events; the national final runs five, with scores combined across disciplines.', 'verified', 'held', NULL, 'day', 'Snow Park Oze Iwakura', 'Katashina, Gunma', 'Japan', ARRAY['other']::text[], ARRAY['https://www.jsba.or.jp/ajstc_site/ajstc33/','https://www.jsba.or.jp/education/ajstc/']::text[], 'verified'),
  ('kaunertal-opening--2015', 'kaunertal-opening--2015', '30th Kaunertal Opening', 'kaunertal-opening', 2015, '2015', NULL, 'contest', '30th anniversary edition, run over three bluebird days on the glacier at 3,000m with the park spread across four locations. Separate pro contest categories for men and women, a Legends Invitational session, the Mega Testival, a Jib''n''Skate Jam and the KTO Music Festival. The mini-ramp returned after a 15-year absence. Sources give no exact competition dates; the World Snowboard Guide page is dated 13 October 2015.', 'unverified', 'held', NULL, 'year', 'Snowpark Kaunertal', 'Kaunertal', 'Austria', ARRAY['jib','other']::text[], ARRAY['https://onboardmag.com/news/snowboarding-events/30th-kaunertal-opening-event-recap.html','https://www.worldsnowboardguide.com/news/30th-kaunertal-opening-2015.html']::text[], 'likely'),
  ('kaunertal-opening--2022', 'kaunertal-opening--2022', '37th Kaunertal Opening (KTO 2022)', 'kaunertal-opening', 2022, '2022-10-15', '2022-11-20', 'contest', 'New two-weekend format: the Jib''n''Playground Edition on 15-16 October and the Testival Open & Snowpark Days on 19-20 November. Cash-for-tricks sessions across several categories plus snowskate competitions and a multi-brand park testival. Powered by Monster Energy. [QA-flagged: non-continuous dates.]', 'verified', 'held', 'Ran as two separate weekends, 15-16 October and 19-20 November 2022; the date range is not continuous.', 'day', 'Snowpark Kaunertal, Kaunertal Glacier', 'Kaunertal', 'Austria', ARRAY['jib','other']::text[], ARRAY['https://whitelines.com/snowboard-culture/snowboard-events/kto-2022-kaunertal-opening-is-back.html']::text[], 'verified'),
  ('king-of-the-mountain-ski-cooper--1981', 'king-of-the-mountain-ski-cooper--1981', '1981 King of the Mountain', 'king-of-the-mountain-ski-cooper', 1981, '1981-04', '1981-04', 'contest', 'Snowboarder/TransWorld timeline: ''Modern competitive snowboarding begins with a small contest held in April at Ski Cooper in Leadville, Colorado.'' Wikipedia names the event ''King of the Mountain''. No podium found in any source opened. Some accounts list a slalom and a freestyle event; not confirmed.', 'unverified', 'held', NULL, 'month', 'Ski Cooper', 'Leadville', 'USA', ARRAY['slalom','other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://en.wikipedia.org/wiki/Snowboarding']::text[], 'likely'),
  ('laax-open--2016', 'laax-open--2016', 'LAAX OPEN 2016', 'laax-open', 2016, '2016-01-18', '2016-01-24', 'contest', 'First LAAX Open, launched after Burton confirmed it would not run the Burton European Open for winter 2016. USD 500,000 prize purse; open entry retained from the BEO.', 'verified', 'held', NULL, 'day', 'LAAX', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html','https://laaxopen.com/en/hall-of-fame/']::text[], 'verified'),
  ('laax-open--2017', 'laax-open--2017', 'LAAX OPEN 2017', 'laax-open', 2017, '2017', NULL, 'contest', 'Snowboard halfpipe and slopestyle. The event joined the FIS Snowboard World Cup circuit in its second year. Confirmed held from the organiser''s Hall of Fame listing; exact dates not sourced.', 'unverified', 'held', NULL, 'year', 'LAAX', 'Laax', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://laaxopen.com/en/hall-of-fame/','https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/']::text[], 'likely'),
  ('laax-open--2018', 'laax-open--2018', 'LAAX OPEN 2018', 'laax-open', 2018, '2018', NULL, 'contest', 'The LAAX Open Hall of Fame lists a snowboard halfpipe champion for 2018 but no snowboard slopestyle champion, so slopestyle appears not to have been awarded that year; the reason was not sourced. Confirmed held from the organiser''s Hall of Fame listing; exact dates not sourced.', 'unverified', 'held', NULL, 'year', 'LAAX', 'Laax', 'Switzerland', ARRAY['halfpipe']::text[], ARRAY['https://laaxopen.com/en/hall-of-fame/']::text[], 'likely'),
