  ('mt-baker-legendary-banked-slalom--2018', 'mt-baker-legendary-banked-slalom--2018', '32nd Legendary Banked Slalom', 'es1', 2018, '2018-02-09', '2018-02-11', 'contest', '450+ participants; a new ''toilet bowl'' feature (a 360-degree bank that funnels back through itself) was added to the course. [v0.3 archive: LBS homepage: "February 9, 10, & 11, 2018".] [v0.3 archive: LBS homepage: "February 9, 10, & 11, 2018".]', 'verified', 'held', NULL, 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://kingsnowboard.com/blogs/news-1/the-32nd-legendary-banked-slalom-mt-baker','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20180112194002/http://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2020', 'mt-baker-legendary-banked-slalom--2020', '2020 Legendary Banked Slalom', 'es1', 2020, '2020-02-07', '2020-02-09', 'contest', '[v0.3 archive: LBS homepage: "34th • February 7, 8, & 9 • 2020".] [v0.3 archive: LBS homepage: "34th • February 7, 8, & 9 • 2020".]', 'verified', 'held', NULL, 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20190603151153/http://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2021', 'mt-baker-legendary-banked-slalom--2021', '2021 Legendary Banked Slalom', 'es1', 2021, '2021', NULL, 'contest', '[v0.3 archive: Archive shows the 2021 dates were published (Feb 5-6-7, 2021) before the postponement notice replaced them.]', 'verified', 'cancelled', 'The 35th Legendary Banked Slalom was scheduled for 5-6-7 February 2021 and then postponed to 2022 because of COVID-19; the organisers'' word was "postponed", not cancelled.', 'year', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2024/feb/01/mt-baker-ski-area-cancels-annual-slalom-race/','https://en.wikipedia.org/wiki/Mt._Baker_Legendary_Banked_Slalom','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20200812142030/http://lbs.mtbaker.us/','https://web.archive.org/web/20201026121157/http://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2022', 'mt-baker-legendary-banked-slalom--2022', '2022 Legendary Banked Slalom', 'es1', 2022, '2022', NULL, 'contest', 'Cascadia Daily News describes a two-year COVID hiatus, with the race returning in 2023. [v0.3 archive: Archive shows the 2022 dates were published (Feb 11-12-13, 2022) before the "POSTPONED TO 2023" notice replaced them.]', 'verified', 'cancelled', 'The 35th Legendary Banked Slalom was rescheduled to 11-12-13 February 2022 and then postponed again, to 2023.', 'year', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2024/feb/01/mt-baker-ski-area-cancels-annual-slalom-race/','http://www.cascadiadaily.com/2023/feb/06/35th-legendary-banked-slalom-returns-to-mount-baker/','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20211127044020/http://lbs.mtbaker.us/','https://web.archive.org/web/20220119064711/http://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2023', 'mt-baker-legendary-banked-slalom--2023', '35th Legendary Banked Slalom', 'es1', 2023, '2023-02-03', '2023-02-05', 'contest', 'First edition after the two-year COVID gap; over 400 racers in qualifying.', 'verified', 'held', NULL, 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2023/feb/06/35th-legendary-banked-slalom-returns-to-mount-baker/','https://www.mountbakerexperience.com/stories/35th-legendary-banked-slalom-results,904','https://lbs.mtbaker.us/results/honor-roll/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2024', 'mt-baker-legendary-banked-slalom--2024', '2024 Legendary Banked Slalom', 'es1', 2024, '2024-02-09', '2024-02-11', 'contest', 'Scheduled as the 36th Legendary Banked Slalom for February 9-11, 2024. Mt. Baker CEO Gwyn Howat: ''El Nino has now washed the 36th Legendary Banked Slalom into 2025.'' The 36th was then run in February 2025. [v0.3 archive: IMPORTANT CORRECTION: the catalog currently lists 2024 as held with dates 2024-02-09/11. The 36th LBS was indeed scheduled for February 9-10-11, 2024 (homepage, 30 Jan 2024) but by 21 March 2024 the homepage read "36th Legendary Banked Slalom Re-scheduled to February 2025". The 2024 event did not run.]', 'verified', 'cancelled', 'Scheduled as the 36th Legendary Banked Slalom for 9-10-11 February 2024, then re-scheduled to February 2025.', 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2024/feb/01/mt-baker-ski-area-cancels-annual-slalom-race/','https://localfreshies.com/mt-baker-cancelled-2024/','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20240130155523/https://lbs.mtbaker.us/','https://web.archive.org/web/20240321202806/https://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2025', 'mt-baker-legendary-banked-slalom--2025', '36th Legendary Banked Slalom', 'es1', 2025, '2025-02-07', '2025-02-09', 'contest', 'Held as the 36th edition, a year after the 36th was washed out in 2024. A cold storm the weekend before and more snow the Wednesday before the race left good conditions. Registration capped at 400. Mt. Baker CEO Gwyn Howat has set the course for over 30 years.', 'verified', 'held', NULL, 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2025/feb/04/mt-baker-ski-area-prepares-for-world-famous-snowboard-race/','https://slushthemagazine.com/blogs/features/2025-mt-baker-legendary-banked-slalom-recap-photos','https://lbs.mtbaker.us/results/honor-roll/','https://lbs.mtbaker.us/results/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2026', 'mt-baker-legendary-banked-slalom--2026', '2026 Legendary Banked Slalom', 'es1', 2026, '2026-02-06', '2026-02-08', 'contest', 'Scheduled as the 37th Legendary Banked Slalom for February 6-8, 2026. Racers registered for 2026 remain eligible for the rescheduled 2027 event, which was moved later in February to allow more snow to build. [v0.3 archive: IMPORTANT CORRECTION: the catalog lists 2026 with dates 2026-02-06/08. The 37th LBS was scheduled for February 6-7-8, 2026 (homepage, 17 Dec 2025); by 22 January 2026 the homepage banner read "37th LBS • Feb. 19-20-21, 2027 • postponement announcement" and it still read that in the most recent capture (June 2026). The 2026 event did not run.]', 'verified', 'cancelled', 'Scheduled as the 37th Legendary Banked Slalom for 6-7-8 February 2026, then postponed to 19-21 February 2027.', 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['http://www.cascadiadaily.com/2026/jan/22/mt-bakers-legendary-banked-slalom-canceled-due-to-unworkable-conditions/','https://lbs.mtbaker.us/37th-2027/','https://localfreshies.com/banked-slalom-event-showcase/','https://web.archive.org/web/20251217181004/https://lbs.mtbaker.us/','https://web.archive.org/web/20260122212354/https://lbs.mtbaker.us/']::text[], 'verified'),
  ('mt-baker-legendary-banked-slalom--2027', 'mt-baker-legendary-banked-slalom--2027', '37th Legendary Banked Slalom', 'es1', 2027, '2027-02-19', '2027-02-21', 'contest', 'Announced by the organiser for Friday-Sunday, February 19-20-21, 2027; also listed on the Mt. Baker Ski Area events page.', 'verified', 'unconfirmed', 'Scheduled, not yet held as of September 2026. This is the rescheduled 37th edition after the February 2026 postponement.', 'day', 'Mt. Baker Ski Area', 'Deming, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://lbs.mtbaker.us/37th-2027/','https://lbs.mtbaker.us/','https://www.mtbaker.us/events/']::text[], 'verified'),
  ('mt-spokane-banked-slalom--2025', 'mt-spokane-banked-slalom--2025', '2025 Mt. Spokane Banked Slalom', 'mt-spokane-banked-slalom', 2025, '2025-03-08', '2025-03-08', 'contest', 'Two timed runs, best run wins; ski and snowboard divisions, Pro/Open and amateur age classes.', 'unverified', 'held', NULL, 'day', 'Mt. Spokane Ski & Snowboard Park', 'Mead, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://www.mtspokane.com/bankedslalom']::text[], 'likely'),
  ('nate-chute-banked-slalom--2026', 'nate-chute-banked-slalom--2026', '2026 Nate Chute Banked Slalom', 'nate-chute-banked-slalom', 2026, '2026-03-14', '2026-03-15', 'contest', 'Dates from a third-party events roundup, not from the organiser.', 'unverified', 'held', NULL, 'day', 'Whitefish Mountain Resort', 'Whitefish, Montana', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://localfreshies.com/banked-slalom-event-showcase/']::text[], 'likely'),
  ('national-collegiate-snowboarding-championships--1989', 'national-collegiate-snowboarding-championships--1989', '1989 National Collegiate Championships', 'national-collegiate-snowboarding-championships', 1989, '1989-12', '1989-12', 'contest', 'December 1989, so it belongs to the 1989-90 season. Single source; no format or podium found.', 'unverified', 'held', NULL, 'month', 'Stratton Mountain', 'Stratton', 'USA', NULL, ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'likely'),
  ('national-snurfing-championships--1968', 'national-snurfing-championships--1968', '1968 National Snurfing Championships', 'national-snurfing-championships', 1968, '1968-02-19', '1968-02-19', 'contest', 'Michigan Snowboard Museum: ''first world snurfing championship is held at blockhouse hill, muskegon state park, mi on feb 19''; 300 participants; organised by Muskegon Community College. Wikipedia''s snowboarding article instead credits Sherman Poppen with organising the first snurfing competition in February 1968 ''at a Michigan ski resort'' - venue and organiser differ between the two accounts.', 'unverified', 'held', NULL, 'day', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html','https://en.wikipedia.org/wiki/Snowboarding']::text[], 'likely'),
  ('national-snurfing-championships--1974', 'national-snurfing-championships--1974', '1974 National Snurfing Championships', 'national-snurfing-championships', 1974, '1974', NULL, 'contest', NULL, 'unverified', 'held', NULL, 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1975', 'national-snurfing-championships--1975', '1975 National Snurfing Championships', 'national-snurfing-championships', 1975, '1975', NULL, 'contest', NULL, 'unverified', 'cancelled', 'Cancelled for lack of snow (Michigan Snowboard Museum timeline).', 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1976', 'national-snurfing-championships--1976', '1976 National Snurfing Championships', 'national-snurfing-championships', 1976, '1976', NULL, 'contest', 'Schlitz beer logo added to the competition bibs this year.', 'unverified', 'held', NULL, 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1977', 'national-snurfing-championships--1977', '1977 National Snurfing Championships', 'national-snurfing-championships', 1977, '1977', NULL, 'contest', NULL, 'unverified', 'held', NULL, 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1978', 'national-snurfing-championships--1978', '1978 National Snurfing Championships', 'national-snurfing-championships', 1978, '1978', NULL, 'contest', 'JEM Corp became an official sponsor and put up $1,000 in cash prizes; first place paid $400. Described by the museum as possibly the first paid snowboard/snurf event.', 'unverified', 'held', NULL, 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1979', 'national-snurfing-championships--1979', '1979 National Snurfing Championships', 'national-snurfing-championships', 1979, '1979', NULL, 'contest', 'Michigan Snowboard Museum gives Blockhouse Hill as the venue and calls 1979 the final year there. Wikipedia''s snowboarding article places the 1979 National Snurfing Championship at Muskegon State Park; other secondary accounts place a 1979 ''World Snurfing Championship'' at Pando near Grand Rapids. Jake Burton Carpenter entered with his own bindinged board and a separate open/modified division was created for him.', 'unverified', 'held', NULL, 'year', 'Blockhouse Hill, Muskegon State Park', 'Muskegon', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html','https://en.wikipedia.org/wiki/Snowboarding']::text[], 'likely'),
  ('national-snurfing-championships--1980', 'national-snurfing-championships--1980', '1980 National Snurfing Championships', 'national-snurfing-championships', 1980, '1980', NULL, 'contest', 'Series moved from Blockhouse Hill to Pando. 600-foot run; a slalom event was added alongside the downhill.', 'unverified', 'held', NULL, 'year', 'Pando Ski Hill', 'Rockford', 'USA', ARRAY['downhill','slalom']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1981', 'national-snurfing-championships--1981', '1981 National Snurfing Championships', 'national-snurfing-championships', 1981, '1981', NULL, 'contest', 'Michigan Snowboard Museum names the 1981 winners but does not name the venue.', 'unverified', 'held', NULL, 'year', NULL, NULL, 'USA', ARRAY['downhill','slalom']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1983', 'national-snurfing-championships--1983', '1983 National Snurfing Championships', 'national-snurfing-championships', 1983, '1983', NULL, 'contest', NULL, 'unverified', 'cancelled', 'Cancelled for lack of snow (Michigan Snowboard Museum timeline).', 'year', NULL, NULL, 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('national-snurfing-championships--1984', 'national-snurfing-championships--1984', '1984 National Snurfing Championships', 'national-snurfing-championships', 1984, '1984', NULL, 'contest', 'Museum timeline says the national snurfing championships ended after this period as snowboard technology outran the Snurfer; no edition is recorded for 1985.', 'unverified', 'held', NULL, 'year', 'Pando Ski Area', 'Rockford', 'USA', ARRAY['other']::text[], ARRAY['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html']::text[], 'likely'),
  ('neil-edgeworth-memorial-banked-slalom--2017', 'neil-edgeworth-memorial-banked-slalom--2017', '20th Annual Neil Edgeworth Memorial Banked Slalom', 'neil-edgeworth-memorial-banked-slalom', 2017, '2017-03-25', '2017-03-26', 'contest', 'Record field of 320 riders aged 6 to 63, on the natural gully beside the Ridge Rocket chair. $5,000 split among the pro winners plus $10,000 across the other categories. Stephanie Haines became the first rider to win the female pro category four years running.', 'verified', 'held', NULL, 'day', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['banked-slalom']::text[], ARRAY['https://www.bigwhite.com/explore-big-white/blog/telus-park/big-white-hosts-20th-annual-neil-edgeworth-banked-slalom']::text[], 'verified'),
  ('neil-edgeworth-memorial-banked-slalom--2019', 'neil-edgeworth-memorial-banked-slalom--2019', '22nd Neil Edgeworth Memorial Banked Slalom', 'neil-edgeworth-memorial-banked-slalom', 2019, '2019', NULL, 'contest', 'BC Snowboard''s 2019 results index links a finals results PDF for the 22nd NEBS. Podiums not yet harvested.', 'verified', 'held', NULL, 'year', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['banked-slalom']::text[], ARRAY['https://www.bcsnowboard.com/2019-results/','https://www.bcsnowboard.com/wp-content/uploads/Finals-Results.NEBS-2019-2.pdf']::text[], 'verified'),
  ('neil-edgeworth-memorial-banked-slalom--2024', 'neil-edgeworth-memorial-banked-slalom--2024', '25th Neil Edgeworth Memorial Banked Slalom', 'neil-edgeworth-memorial-banked-slalom', 2024, '2024', NULL, 'contest', '25th anniversary edition, organised with BC Snowboard. Dates not given in the source (article posted 1 April 2024).', 'unverified', 'held', NULL, 'year', 'TELUS Park, Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['banked-slalom']::text[], ARRAY['https://www.bigwhite.com/explore-big-white/blog/telus-park/25-years-nebs']::text[], 'likely'),
  ('neil-edgeworth-memorial-banked-slalom--2025', 'neil-edgeworth-memorial-banked-slalom--2025', '26th Neil Edgeworth Memorial Banked Slalom', 'neil-edgeworth-memorial-banked-slalom', 2025, '2025-03-28', '2025-03-30', 'contest', '255 riders entered, from juniors to riders in their sixties. Big White reported Chris Bradley as the fastest men''s time (given as 1:26:51 in the source).', 'verified', 'held', NULL, 'day', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['banked-slalom']::text[], ARRAY['https://www.bigwhite.com/explore-big-white/blog/mountain-news/nebs-26yrs-tradition','https://www.bcsnowboard.com/2025-event-results/']::text[], 'verified'),
  ('neil-edgeworth-memorial-banked-slalom--2026', 'neil-edgeworth-memorial-banked-slalom--2026', '27th Annual Neil Edgeworth Memorial Banked Slalom', 'neil-edgeworth-memorial-banked-slalom', 2026, '2026-03-20', '2026-03-22', 'contest', 'Two runs, one Saturday and one Sunday, on either the Traditional Gully or the TELUS Park course. Pro (female/male open), amateur (ten age groups from 11-and-under to 60+, plus Pro Masters 40+) and para (female/male open) divisions.', 'verified', 'held', NULL, 'day', 'Big White Ski Resort', 'Kelowna', 'Canada', ARRAY['banked-slalom']::text[], ARRAY['https://www.bcsnowboard.com/wp-content/uploads/2026-27th-Annual-NEBS-Event-Information.March-20-22-2026.pdf']::text[], 'verified'),
  ('nescafe-champs-leysin--2010', 'nescafe-champs-leysin--2010', 'Nescafe Open Champs 2010', 'nescafe-champs-leysin', 2010, '2010', NULL, 'contest', 'Swatch TTR 4-Star halfpipe. The contest returned to Leysin after three seasons in Valais, with Nescafe back as title sponsor after previously backing it from 1994 to 2006. Return to Leysin after three seasons in Valais, and the return of Nescafé as title sponsor (a partner from 1994 to 2006). Announced as a Swatch TTR 4Star halfpipe competition. Exact dates not stated in the article I opened.', 'unverified', 'held', NULL, 'year', 'Leysin', 'Leysin', 'Switzerland', ARRAY['halfpipe']::text[], ARRAY['https://www.worldsnowboardfederation.org/nescafe-open-champs-in-leysin-2010-the-oldest-european-snowboard-event/']::text[], 'likely'),
  ('nescafe-champs-leysin--2011', 'nescafe-champs-leysin--2011', '20th NESCAFE Champs', 'nescafe-champs-leysin', 2011, '2011', NULL, 'contest', '20th anniversary edition. Swatch TTR 4-Star, USD 50,000 prize purse and 850 TTR world ranking points to the winners. Slopestyle course combined kickers, a halfpipe and a wallride; warm spring-like conditions across the region but the course held up. The World Snowboard Guide report is dated 12 February 2011; exact competition dates were not given. Billed as the 20th anniversary of the Nescafé Champs Leysin and as the oldest snowboard event in Europe. Slopestyle course combining kickers, a halfpipe and a wallride. Winners took USD 50,000 and 850 Swatch TTR world ranking points, which corresponds to a 5Star rating.', 'unverified', 'held', NULL, 'year', 'Leysin', 'Leysin', 'Switzerland', ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardguide.com/news/cilka-sadar---lucien-koch-win-2011-champ-in-leysin.html']::text[], 'likely'),
  ('nescafe-champs-leysin--2012', 'nescafe-champs-leysin--2012', '21st Nescafé Champs', 'nescafe-champs-leysin', 2012, '2012-03-04', NULL, 'contest', '21st edition. Not present in the wave-1 edition list.', 'verified', 'held', NULL, 'day', NULL, 'Leysin', 'Switzerland', ARRAY['slopestyle']::text[], ARRAY['https://www.lematin.ch/story/le-maitre-du-slopestyle-s-impose-a-leysin-537053620798']::text[], 'verified'),
  ('nescafe-champs-leysin--2013', 'nescafe-champs-leysin--2013', 'Nescafe Champs 2013', 'nescafe-champs-leysin', 2013, '2013-03-06', '2013-03-10', 'contest', 'TTR 5-Star. Course again ran a halfpipe into the classic slopestyle kickers and rails.', 'verified', 'held', NULL, 'day', 'Leysin', 'Leysin', 'Switzerland', ARRAY['slopestyle']::text[], ARRAY['https://snowboarding.transworld.net/news/get-ready-for-the-nescafe-champs-in-leysin-switzerland-march-6-10/']::text[], 'verified'),
  ('nippon-open--2008', 'nippon-open--2008', '2008 Nissan X-Trail Nippon Open', 'nippon-open', 2008, '2008-02-26', '2008-03-02', 'contest', '5Star event on the TTR tour, reported as drawing over 40,000 spectators. The parkstyle finals ran after heavy snow and high winds earlier in the week, with semi-finals and finals held back to back; Mikkel Bang and Jenny Jones won. Winners took 8,000 points toward the Burton Global Open Series championship.', 'verified', 'held', NULL, 'day', 'ALTS Bandai', 'Bandai, Fukushima', 'Japan', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://whitelines.com/archive/news/japan-beckons-riders-for-5-star-nissan-x-trail-nippon-open.html','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html']::text[], 'verified'),
  ('nippon-open--2009', 'nippon-open--2009', '2009 Nissan X-Trail Nippon Open', 'nippon-open', 2009, '2009-02-24', '2009-03-01', 'contest', 'Fifth stop of the 2008/09 Burton Global Open Series, as announced in the series calendar.', 'unverified', 'held', NULL, 'day', 'ALTS Bandai', 'Bandai, Fukushima', 'Japan', NULL, ARRAY['https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[], 'likely'),
  ('niseko-moiwa-banked-slalom--2025', 'niseko-moiwa-banked-slalom--2025', 'NISEKO MOIWA BANKED SLALOM 2025', 'niseko-moiwa-banked-slalom', 2025, '2025-03-29', '2025-03-29', 'contest', 'Five divisions: snowskate, ski, snowboard elementary, snowboard open (junior-high and up) and snowboard master (43+). Entries opened 15 March. Official site moiwabankedslalom.com.', 'verified', 'held', 'Scheduled for 29 March with 30 March held as a bad-weather reserve day; practice on 28 March.', 'day', 'Niseko Moiwa Ski Resort', 'Niseko, Hokkaido', 'Japan', ARRAY['banked-slalom']::text[], ARRAY['https://niseko-moiwa.jp/ja/news/2025/03/10/532/']::text[], 'verified'),
  ('north-alps-banked-slalom--2026', 'north-alps-banked-slalom--2026', '2026 BANKED SLALOM TGK supported by Gyunyu Sekken (Tsugaike round)', 'north-alps-banked-slalom', 2026, '2026-04-04', '2026-04-05', 'contest', 'Second race of the three-round North Alps Banked Slalom series (Hakuba Iwatake, Tsugaike, Hakuba Happo-one). Expanded to two days with 260 participants a day; ski, snowboard, snowbike and parent-child divisions added to the previously snowboard-only programme. Top six in each category awarded. Main sponsor Milk Soap (Gyunyu Sekken), supported by Red Bull Japan among others.', 'verified', 'held', NULL, 'day', 'Tsugaike Mountain Resort, Hannoki Special Course', 'Otari, Nagano (Hakuba valley)', 'Japan', ARRAY['banked-slalom']::text[], ARRAY['https://steep.jp/en/custom/tsugaike-banked-slalom/']::text[], 'verified'),
  ('norwegian-snowboard-championships--2011', 'norwegian-snowboard-championships--2011', 'Norwegian Snowboard Championships 2011', 'norwegian-snowboard-championships', 2011, '2011-03', NULL, 'contest', 'Halfpipe at Oslo Vinterpark on 27 March 2011; boardercross, big air and slopestyle at Trysil. Rated 3-Star TTR. Fields spanned ages 12 to 37. Silje Norendal, then 17, took two golds, two silvers and the King''s Cup.', 'unverified', 'held', NULL, 'month', 'Oslo Vinterpark and Trysil', 'Oslo and Trysil', 'Norway', ARRAY['halfpipe','boardercross','big-air','slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-3star-ttr-norwegian-championships/']::text[], 'likely'),
  ('oakley-girl-sessions-ruka--2010', 'oakley-girl-sessions-ruka--2010', '7th Oakley Girlsessions', 'oakley-girl-sessions-ruka', 2010, '2010-04-08', '2010-04-11', 'contest', 'Swatch TTR 3-Star. Programme combined the TTR slopestyle with a team contest, a pipe competition and a freeski slopestyle, and was open to riders of all ability levels.', 'verified', 'held', NULL, 'day', 'Ruka BatteryPark', 'Ruka, Kuusamo', 'Finland', ARRAY['slopestyle','halfpipe','team']::text[], ARRAY['https://www.worldsnowboardfederation.org/7th-edition-of-oakley-girlsessions-at-ruka-finland-8-11-4-2010/']::text[], 'verified'),
  ('olympic-snowboarding--1998', 'olympic-snowboarding--1998', '1998 Nagano Winter Olympics', 'olympic-snowboarding', 1998, '1998-02-08', '1998-02-12', 'contest', 'First Olympic snowboarding. Four medal events, men''s and women''s giant slalom and halfpipe. Held under FIS jurisdiction rather than the snowboarders'' own ISF, which prompted a boycott of qualification by Terje Haakonsen. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Mt. Yakebitai, Shiga Kogen (giant slalom) / Kanbayashi Sports Park (halfpipe)', 'Yamanouchi', 'Japan', ARRAY['giant-slalom','halfpipe']::text[], ARRAY['https://www.olympedia.org/editions/46/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2002', 'olympic-snowboarding--2002', '2002 Salt Lake City Winter Olympics', 'olympic-snowboarding', 2002, '2002-02-10', '2002-02-15', 'contest', 'Giant slalom was replaced by parallel giant slalom. Olympedia records 118 athletes from 19 nations. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Park City Mountain Resort', 'Park City, Utah', 'United States', ARRAY['halfpipe','parallel-giant-slalom']::text[], ARRAY['https://www.olympedia.org/editions/47/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2006', 'olympic-snowboarding--2006', '2006 Torino Winter Olympics', 'olympic-snowboarding', 2006, '2006-02-12', '2006-02-23', 'contest', 'Snowboard cross (boardercross) added for men and women, taking the programme to six medal events. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Bardonecchia', 'Bardonecchia, Piedmont', 'Italy', ARRAY['halfpipe','boardercross','parallel-giant-slalom']::text[], ARRAY['https://www.olympedia.org/editions/49/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2010', 'olympic-snowboarding--2010', '2010 Vancouver Winter Olympics', 'olympic-snowboarding', 2010, '2010-02-15', '2010-02-27', 'contest', 'Six medal events, athletes from 27 nations per Olympedia. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Cypress Mountain', 'West Vancouver, British Columbia', 'Canada', ARRAY['boardercross','halfpipe','parallel-giant-slalom']::text[], ARRAY['https://www.olympedia.org/editions/57/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2014', 'olympic-snowboarding--2014', '2014 Sochi Winter Olympics', 'olympic-snowboarding', 2014, '2014-02-06', '2014-02-22', 'contest', 'Slopestyle and parallel slalom both made their Olympic debut; 10 medal events, 237 competitors from 31 nations per Olympedia. Parallel slalom has not been held at any subsequent Games. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Rosa Khutor Extreme Park', 'Krasnaya Polyana', 'Russia', ARRAY['slopestyle','halfpipe','boardercross','parallel-giant-slalom','parallel-slalom']::text[], ARRAY['https://www.olympedia.org/editions/58/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2018', 'olympic-snowboarding--2018', '2018 PyeongChang Winter Olympics', 'olympic-snowboarding', 2018, '2018-02-10', '2018-02-24', 'contest', 'Big air made its Olympic debut and parallel slalom was dropped. 10 medal events, 244 competitors from 29 nations per Olympedia. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Phoenix Snow Park', 'Bongpyeong, Mountain Cluster', 'South Korea', ARRAY['slopestyle','halfpipe','boardercross','big-air','parallel-giant-slalom']::text[], ARRAY['https://www.olympedia.org/editions/60/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2022', 'olympic-snowboarding--2022', '2022 Beijing Winter Olympics', 'olympic-snowboarding', 2022, '2022-02-05', '2022-02-15', 'contest', 'Mixed team snowboard cross added, taking the programme to 11 medal events. Big air was held at Big Air Shougang, a permanent ramp on a former steelworks site in Beijing; all other events at Genting Snow Park. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Genting Snow Park, Zhangjiakou / Big Air Shougang, Beijing', 'Zhangjiakou and Beijing', 'China', ARRAY['slopestyle','parallel-giant-slalom','halfpipe','boardercross','team','big-air']::text[], ARRAY['https://www.olympedia.org/editions/62/sports/SBD']::text[], 'verified'),
  ('olympic-snowboarding--2026', 'olympic-snowboarding--2026', '2026 Milano-Cortina Winter Olympics', 'olympic-snowboarding', 2026, '2026-02-05', '2026-02-18', 'contest', 'Most recent Games as of September 2026. 11 medal events, 234 competitors from 27 nations per Olympedia. Dates are the first and last day of snowboarding competition as listed by Olympedia, not the dates of the Games as a whole.', 'verified', 'held', NULL, 'day', 'Mottolino Montagna del Divertimento / Carosello 3000, Livigno', 'Livigno, Sondrio', 'Italy', ARRAY['big-air','parallel-giant-slalom','halfpipe','boardercross','team','slopestyle']::text[], ARRAY['https://www.olympedia.org/editions/72/sports/SBD']::text[], 'verified'),
