  ('oneill-evolution--2011', 'oneill-evolution--2011', 'O''Neill Evolution 2011', 'oneill-evolution', 2011, '2011-01-02', '2011-01-08', 'contest', 'Four contests in the week: halfpipe and slopestyle, both 6Star, both for men and women. First year women started in both disciplines alongside the men.', 'verified', 'held', NULL, 'day', 'Bolgen, Jakobshorn', 'Davos', 'Switzerland', ARRAY['halfpipe','slopestyle']::text[], ARRAY['https://www.boardshop.de/boardmag/snowboard/news/oneill-evolution-2011-in-davos-vom-2-bis-8-januar_aid_16198.html']::text[], 'verified'),
