  ('oneill-evolution--2013', 'oneill-evolution--2013', 'O''Neill Evolution 2013', 'oneill-evolution', 2013, '2013-01-07', '2013-01-13', 'contest', 'Big air run as a 6Star and halfpipe as a 5Star; 120 competitors, USD 150,000 in prize money, entry limited to the TTR top 100. Last edition of the series.', 'verified', 'held', NULL, 'day', 'Jakobshorn base', 'Davos', 'Switzerland', ARRAY['big-air','halfpipe']::text[], ARRAY['https://www.worldsnowboardguide.com/events/o-neill-evolution-2013.html','https://www.worldsnowboardguide.com/news/no-o-neill-evolution-in-davos-this-season.html']::text[], 'verified'),
  ('oneill-evolution--2014', 'oneill-evolution--2014', 'O''Neill Evolution 2014', 'oneill-evolution', 2014, '2014', NULL, 'contest', 'Recorded as a not-held year rather than an edition.', 'verified', 'cancelled', 'No event held. O''Neill marketing director Claudio Curiger said the brand was working on a new strategy and that major events were ''no longer an issue for the time being''. O''Neill kept other Davos commitments such as park sponsorship and its flagship store.', 'year', 'Davos', 'Davos', 'Switzerland', NULL, ARRAY['https://www.worldsnowboardguide.com/news/no-o-neill-evolution-in-davos-this-season.html']::text[], 'verified'),
  ('op-pro-snowboarding--1989', 'op-pro-snowboarding--1989', '1989 OP Pro of Snowboarding', 'op-pro-snowboarding', 1989, '1989', NULL, 'contest', 'Single-source (Snowboarder/TransWorld 1980s timeline: ''OP Pro of Snowboarding held at June Mountain, California''). No dates, no podium. Disciplines inferred from Craig Kelly''s published career timeline, which lists halfpipe and giant slalom results at a 1989 OP Pro - a rider biography, so not used for placings.', 'unverified', 'held', NULL, 'year', 'June Mountain', 'June Lake', 'USA', ARRAY['halfpipe','giant-slalom']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'likely'),
  ('op-wintersurf--1991', 'op-wintersurf--1991', '1991 OP Wintersurf', 'op-wintersurf', 1991, '1991-02', '1991-02', 'contest', 'February 1991. Won by professional surfer Gary Elkerton, which the magazine used to make the point that surfing is harder to pick up than snowboarding. Single source.', 'unverified', 'held', NULL, 'month', 'Huntington Beach and Bear Mountain', NULL, 'USA', ARRAY['other']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[], 'likely'),
  ('pacwest-banked-slalom--2022', 'pacwest-banked-slalom--2022', '1st PacWest Banked Slalom', 'pacwest-banked-slalom', 2022, '2022', NULL, 'contest', 'Inaugural edition, created and organised by Marcel Dolak with Karter Riach, Olivia Cayley and volunteer diggers. Exact dates not given in the sources found.', 'unverified', 'held', NULL, 'year', 'Summit East, The Summit at Snoqualmie', 'Snoqualmie Pass, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://thesnowboardersjournal.com/blogs/exclusives/pacwest-banked-slalom-2022','https://www.summitatsnoqualmie.com/events/pacwest-banked-slalom']::text[], 'likely'),
