  ('pacwest-banked-slalom--2026', 'pacwest-banked-slalom--2026', '5th Annual PacWest Banked Slalom', 'pacwest-banked-slalom', 2026, '2026-03-13', '2026-03-15', 'contest', 'Scheduled for March 13-15, 2026 as the fifth annual event, with 21 divisions for ages 6 to 60+.', 'verified', 'cancelled', 'Cancelled for insufficient snow.', 'day', 'Summit East, The Summit at Snoqualmie', 'Snoqualmie Pass, Washington', 'USA', ARRAY['banked-slalom']::text[], ARRAY['https://www.summitatsnoqualmie.com/events/pacwest-banked-slalom']::text[], 'verified'),
  ('pleasure-jam--2009', 'pleasure-jam--2009', 'Horsefeathers Pleasure Jam 2009', 'pleasure-jam', 2009, '2009-11-13', '2009-11-15', 'contest', 'Swatch TTR World Snowboard Tour 4-Star, USD 15,000 prize purse. Separate judging for female riders and an open-public-park category for less experienced entrants.', 'verified', 'held', NULL, 'day', 'Atomic Superpark Dachstein', 'Ramsau am Dachstein (Schladming-Dachstein)', 'Austria', ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/horsefeather-pleasure-jam-09-in-dachstain/']::text[], 'verified'),
  ('pleasure-jam--2015', 'pleasure-jam--2015', 'Pleasure Jam Vol. 13', 'pleasure-jam', 2015, '2015-11-28', '2015-11-29', 'contest', 'First tour stop of the World Snowboard Tour northern-hemisphere season and of the QParks Snowboard Tour; contested on a pro kicker line.', 'verified', 'held', 'Originally scheduled for early November 2015 and postponed: the Superpark opened on 24 October but snow was insufficient to build a compliant World Snowboard Tour International setup.', 'day', 'Superpark Dachstein, Dachstein Glacier', 'Ramsau am Dachstein (Schladming-Dachstein)', 'Austria', ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/pleasure-jam-vol-13-postponed/']::text[], 'verified'),
