  ('qparks-snowboard-tour--2016', 'qparks-snowboard-tour--2016', 'QParks Snowboard Tour 2016/17', 'qparks-snowboard-tour', 2016, '2016-11-19', '2017-04-22', 'contest', 'Seventh season, EUR 40,000 total prize money. Ten stops: Pleasure Jam, Superpark Dachstein (19 Nov 2016); Battle ROJal, Snowpark Schoeneben (7 Jan 2017); Penken Battle, Vans Penken Park (14 Jan); Blue Tomato Plan P, Superpark Planai (28 Jan); Nock''n''Rock, Snowpark Turracher Hoehe (11 Feb); Sick Trick Tour Open, Snowpark Kitzbuehel (18 Feb); Gold & Glory Golden, Roofpark Axamer Lizum (25 Feb); Oakley Schilthorn Open, Skyline Snowpark Schilthorn (11 Mar); Shred Masters Feldberg, Badenova Snowpark Feldberg (18 Mar); Roof Battle, Superpark Dachstein (22 Apr). Covers Austria, Germany, Italy and Switzerland.', 'verified', 'held', NULL, 'day', NULL, NULL, 'multiple', ARRAY['slopestyle','rail-jam','jib']::text[], ARRAY['https://www.worldsnowboardfederation.org/qparks-snowboard-tour-set-for-201617/']::text[], 'verified'),
