  ('rey-del-park--2012', 'rey-del-park--2012', 'VIII Rey del Park', 'rey-del-park', 2012, '2012-09-02', '2012-09-02', 'contest', 'Eighth edition and the first to count for the WSF South America Tour. WSF/TTR 2-Star slopestyle, USD 3,000 prize money, around 80 professional athletes from Chile, Argentina, Brazil, Spain, the USA and Canada.', 'verified', 'held', NULL, 'day', 'El Colorado', 'Farellones / Lo Barnechea, Santiago Metropolitan Region', 'Chile', ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/viii-rey-del-park-el-colorado-chile/','https://www.worldsnowboardfederation.org/winter-season-in-chile/']::text[], 'verified'),
  ('rey-del-park--2013', 'rey-del-park--2013', 'Lippi Rey del Park 2013', 'rey-del-park', 2013, '2013-07-27', '2013-07-28', 'contest', 'USD 8,000 in prizes; open to skiers as well as snowboarders. Described by the WSF as taking place in the best terrain park in South America.', 'verified', 'held', NULL, 'day', 'El Colorado', 'Farellones / Lo Barnechea, Santiago Metropolitan Region', 'Chile', ARRAY['slopestyle']::text[], ARRAY['https://www.worldsnowboardfederation.org/lippi-king-of-the-park-in-el-colorado-chile/']::text[], 'verified'),
  ('roxy-chicken-jam--2006', 'roxy-chicken-jam--2006', 'Roxy Chicken Jam Europe 2006', 'roxy-chicken-jam', 2006, '2006-12-12', '2006-12-15', 'contest', 'Wikipedia gives Kaprun; the WSF''s provisional 06/07 women''s tour calendar, published 24 October 2006, listed the European Roxy Chicken Jam at St Moritz, Switzerland. The two sources disagree on venue.', 'unverified', 'held', NULL, 'day', NULL, 'Kaprun', 'Austria', NULL, ARRAY['https://en.wikipedia.org/wiki/Chicken_Jam','https://www.worldsnowboardfederation.org/ttr-women-tour-announced/']::text[], 'likely'),
