  ('toyota-big-air--2012', 'toyota-big-air--2012', '16th Toyota Big Air', 'toyota-big-air', 2012, '2012', NULL, 'contest', 'Moved indoors to the Sapporo Dome as a ''full model change'', with a 36 m temporary in-run scaffold.', 'verified', 'held', NULL, 'year', 'Sapporo Dome', 'Sapporo', 'Japan', ARRAY['big-air']::text[], ARRAY['https://ja.wikipedia.org/wiki/TOYOTA_BIG_AIR','https://en.wikipedia.org/wiki/Toyota_Big_Air']::text[], 'verified'),
