  ('winter-dew-tour--2012-c', 'winter-dew-tour--2012-c', 'Dew Tour Mountain Championships 2012 (Breckenridge)', 'winter-dew-tour', 2012, '2012-12-13', '2012-12-16', 'contest', 'First season under the restructured single-winter-stop format (''the lone Winter Dew Tour stop''). A Main Street rail jam ran alongside the mountain events (recorded as ''jib'').', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib']::text[], ARRAY['https://www.newschoolers.com/news/read/2012-Dew-Tour-Schedule-Announced','https://news.vailresorts.com/2013-04-04-Winter-Dew-Tour-Returns-to-Breckenridge-in-2013']::text[], 'verified'),
  ('winter-dew-tour--2013', 'winter-dew-tour--2013', 'Dew Tour Mountain Championships 2013 (Breckenridge)', 'winter-dew-tour', 2013, '2013-12-12', '2013-12-15', 'contest', 'Announced as the Mountain Championships leg of the three-stop 2013 Dew Tour (Ocean City, San Francisco, Breckenridge). Snowboard discipline list not confirmed.', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', NULL, ARRAY['https://news.vailresorts.com/2013-04-04-Winter-Dew-Tour-Returns-to-Breckenridge-in-2013']::text[], 'verified'),
  ('winter-dew-tour--2014', 'winter-dew-tour--2014', 'Dew Tour Mountain Championships 2014 (Breckenridge)', 'winter-dew-tour', 2014, '2014-12-11', '2014-12-15', 'contest', 'Men''s and women''s snowboard slopestyle and superpipe plus men''s Snowboard Streetstyle (recorded as ''jib''). Described as the seventh straight year at Breckenridge. Dates from a secondary event listing, not an organiser release.', 'unverified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib']::text[], ARRAY['https://www.worldsnowboardguide.com/events/winter-dew-tour-breckenridge-2014.html']::text[], 'likely'),
  ('winter-dew-tour--2015', 'winter-dew-tour--2015', 'Dew Tour Breckenridge 2015', 'winter-dew-tour', 2015, '2015-12-10', '2015-12-13', 'contest', 'Men''s and women''s snowboard superpipe and slopestyle finals plus a Snowboard Streetstyle final (recorded as ''jib'').', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib']::text[], ARRAY['https://news.vailresorts.com/2015-12-08-Dew-Tour-Announces-Event-and-Broadcast-Schedule-from-Breckenridge,-December-10-13']::text[], 'verified'),
  ('winter-dew-tour--2016', 'winter-dew-tour--2016', 'Dew Tour Breckenridge 2016', 'winter-dew-tour', 2016, '2016-12-08', '2016-12-11', 'contest', 'Run in Breckenridge''s Freeway Terrain Park. Individual men''s and women''s slopestyle and pipe, plus a new brand Team Challenge format (recorded as ''team''). First winter edition under TEN: The Enthusiast Network ownership.', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','team']::text[], ARRAY['https://news.vailresorts.com/2016-08-30-Dew-Tour-Announces-Return-to-Breckenridge-for-Winter-2016-Ski-and-Snowboard-Competition']::text[], 'verified'),
  ('winter-dew-tour--2017', 'winter-dew-tour--2017', 'Dew Tour Breckenridge 2017', 'winter-dew-tour', 2017, '2017-12-14', '2017-12-17', 'contest', 'Men''s and women''s snowboard slopestyle and superpipe (a U.S. Ski & Snowboard Olympic qualifying event), a combined ski/snowboard Streetstyle (recorded as ''jib'') and a Team Challenge on a modified superpipe/jib/jump course (recorded as ''team'').', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib','team']::text[], ARRAY['https://news.vailresorts.com/2017-10-17-Schedule-Announced-for-2017-Winter-Dew-Tour-at-Breckenridge-Ski-Resort,-Dec-14-17']::text[], 'verified'),
  ('winter-dew-tour--2018', 'winter-dew-tour--2018', 'Dew Tour Breckenridge 2018', 'winter-dew-tour', 2018, '2018-12-13', '2018-12-16', 'contest', 'Eleventh and final Breckenridge edition. Men''s and women''s ski and snowboard slopestyle and halfpipe, a para snowboard competition (recorded as ''other''), a 12-brand Team Challenge, and a Streetstyle jam in downtown Breckenridge (recorded as ''jib'').', 'verified', 'held', NULL, 'day', 'Breckenridge Ski Resort', 'Breckenridge, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib','team','other']::text[], ARRAY['https://news.vailresorts.com/2018-06-07-Winter-Dew-Tour-Returns-to-Breckenridge-December-13-16,-2018']::text[], 'verified'),
  ('winter-dew-tour--2020', 'winter-dew-tour--2020', 'Dew Tour Copper Mountain 2020', 'winter-dew-tour', 2020, '2020-02-06', '2020-02-09', 'contest', 'First Copper Mountain edition after 11 years at Breckenridge. Men''s and women''s halfpipe, slopestyle in Copper''s Central Park, para snowboard (recorded as ''other'') and the Team Challenge. Note the calendar-year gap: the previous edition was December 2018, so no Winter Dew Tour was held in calendar 2019.', 'verified', 'held', NULL, 'day', 'Copper Mountain Resort', 'Copper Mountain, Colorado', 'USA', ARRAY['superpipe','slopestyle','team','other']::text[], ARRAY['https://www.mensjournal.com/adventure/winter-dew-tour-heads-to-copper-mountain-colorado-february-6-9-2020/','https://en.wikipedia.org/wiki/Dew_Tour']::text[], 'verified'),
  ('winter-dew-tour--2021', 'winter-dew-tour--2021', 'Dew Tour Copper Mountain 2021', 'winter-dew-tour', 2021, '2021-12-15', '2021-12-19', 'contest', 'Beijing 2022 Olympic qualifying event. DATE CONFLICT: U.S. Ski & Snowboard gives December 15-19, 2021; Summit Daily''s preview gives December 16-19. More than 200 athletes from 17 countries in ski and snowboard superpipe, slopestyle and adaptive snowboard slalom (recorded as ''other'').', 'unverified', 'held', NULL, 'day', 'Copper Mountain Resort', 'Copper Mountain, Colorado', 'USA', ARRAY['superpipe','slopestyle','other']::text[], ARRAY['https://www.usskiandsnowboard.org/index.php/news/dew-tour-olympic-qualifier-kicks','https://gearjunkie.com/news/dew-tour-copper-mountain-live-coverage']::text[], 'likely'),
  ('winter-dew-tour--2023', 'winter-dew-tour--2023', 'Dew Tour Copper Mountain 2023', 'winter-dew-tour', 2023, '2023-02-24', '2023-02-26', 'contest', 'Based in Copper''s Center Village. Men''s and women''s ski and snowboard superpipe and slopestyle, a Super Streetstyle (recorded as ''jib'') and superpipe high air / best trick jams (recorded as ''other''). No Winter Dew Tour was held in calendar 2022.', 'verified', 'held', NULL, 'day', 'Copper Mountain Resort', 'Copper Mountain, Colorado', 'USA', ARRAY['superpipe','slopestyle','jib','other']::text[], ARRAY['https://dewtour.com/stories/winter-dew-tour-2023-copper-mountain-february-24-26/','https://www.usskiandsnowboard.org/news/2023-copper-mountain-dew-tour-preview']::text[], 'verified'),
  ('winter-dew-tour--2024', 'winter-dew-tour--2024', 'Dew Tour Copper Mountain 2024', 'winter-dew-tour', 2024, '2024-03-08', '2024-03-10', 'contest', 'Final Winter Dew Tour. Dates are as stated in the headlines of the Dew Tour and PR Newswire announcements; neither page body could be retrieved (dewtour.com blocked the fetcher via robots.txt). Discipline list not confirmed. Dew Tour announced in 2024 that the winter event would not return from 2025 onward.', 'unverified', 'held', NULL, 'day', 'Copper Mountain Resort', 'Copper Mountain, Colorado', 'USA', NULL, ARRAY['https://dewtour.com/stories/winter-dew-tour-copper-mountain-date-announcement-march-2024/','https://www.prnewswire.com/news-releases/winter-dew-tour-snowboard-and-ski-competition-and-festival-returns-to-copper-mountain-march-8-10-2024-301971535.html','https://en.wikipedia.org/wiki/Dew_Tour']::text[], 'likely'),
