  ('winter-x-games--1997', 'winter-x-games--1997', 'Winter X Games I (1997)', 'winter-x-games', 1997, '1997-01-30', '1997-02-02', 'contest', 'First edition. Snowboard Magazine''s history names Snow Summit, Big Bear as the site and lists slopestyle, big air, snowboarder X and halfpipe, noting the pipe was 12 feet tall. Non-snowboard disciplines included ice climbing, snow mountain bike racing and shovel racing.', 'unverified', 'held', NULL, 'day', 'Snow Summit', 'Big Bear Lake, California', 'USA', ARRAY['halfpipe','slopestyle','big-air','boardercross']::text[], ARRAY['https://en.wikipedia.org/wiki/X_Games','https://snowboardmag.com/stories/history-winter-x-games-part-1']::text[], 'likely'),
  ('winter-x-games--1998', 'winter-x-games--1998', 'Winter X Games II (1998)', 'winter-x-games', 1998, '1998-01', NULL, 'contest', 'Aspen Daily News gives January 1998; no exact dates found. Freeskiing, snowmobile SnoCross and skiboarding added to the overall programme. Discipline list is from a Snowboard Magazine results retrospective that tracked only halfpipe, slopestyle and big air; whether snowboarder X ran is unconfirmed.', 'unverified', 'held', NULL, 'month', 'Crested Butte Mountain Resort', 'Crested Butte, Colorado', 'USA', ARRAY['halfpipe','slopestyle','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/X_Games','https://www.aspendailynews.com/winter-x-games-a-brief-history/article_3459d151-30c8-5345-a0a9-2837bdfe8211.html','https://snowboardmag.com/stories/winter-x-games-14-years-results']::text[], 'likely'),
