  ('winter-x-games--2000', 'winter-x-games--2000', 'Winter X Games IV (2000)', 'winter-x-games', 2000, '2000-02-03', '2000-02-06', 'contest', 'First East Coast Winter X Games. Aspen Daily News reports snowboard SuperPipe added this year and the pipe wall height raised to 15 feet. Record attendance reported as 83,500.', 'unverified', 'held', NULL, 'day', 'Mount Snow', 'West Dover, Vermont', 'USA', ARRAY['superpipe','slopestyle','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/X_Games','https://www.aspendailynews.com/winter-x-games-a-brief-history/article_3459d151-30c8-5345-a0a9-2837bdfe8211.html','https://snowboardmag.com/stories/winter-x-games-14-years-results']::text[], 'likely'),
