  ('world-rookie-finals--2015', 'world-rookie-finals--2015', 'Völkl World Rookie Finals 2015', 'world-rookie-finals', 2015, '2015-04', NULL, 'contest', '3Star TTR event where the World Rookie Champion titles were awarded. Exact dates not given in the source.', 'unverified', 'held', NULL, 'month', 'Ischgl', 'Ischgl', 'Austria', ARRAY['slopestyle']::text[], ARRAY['https://www.worldrookietour.com/the-tour/','https://www.worldsnowboardfederation.org/?s=Ischgl']::text[], 'likely'),
  ('world-rookie-finals--2017', 'world-rookie-finals--2017', '2017 World Rookie Finals, Kitzsteinhorn', 'world-rookie-finals', 2017, '2017-04-04', '2017-04-09', 'contest', 'First World Rookie Finals at the Kitzsteinhorn. Climax of a 2016/17 World Rookie Tour season of eleven qualifying events across Chile, Australia, Bulgaria, Scandinavia, the Alps, Japan and North America. Programme included social dinners, workshops and a final party alongside the contests.', 'verified', 'held', NULL, 'day', 'Kitzsteinhorn', 'Kaprun / Zell am See', 'Austria', ARRAY['slopestyle','halfpipe']::text[], ARRAY['https://www.worldsnowboardfederation.org/2017-world-rookie-finals-kitzsteinhorn-kaprun/']::text[], 'verified'),
  ('world-rookie-finals--2024', 'world-rookie-finals--2024', 'World Rookie Snowboard Finals 2024', 'world-rookie-finals', 2024, '2024', NULL, 'contest', 'Confirmed only by a WSF news item dated 27 March 2024; venue and dates not established in this pass.', 'unverified', 'held', NULL, 'year', NULL, NULL, NULL, NULL, ARRAY['https://www.worldsnowboardfederation.org/snowboardings-future-stars-at-the-2024-world-rookie-snowboard-finals/']::text[], 'likely'),
  ('world-rookie-finals--2025', 'world-rookie-finals--2025', 'World Rookie Snowboard Finals 2025', 'world-rookie-finals', 2025, '2025', NULL, 'contest', 'Reported by WSF on 8 April 2025. Exact dates not established in this pass.', 'unverified', 'held', NULL, 'year', 'Kitzsteinhorn', 'Kaprun', 'Austria', NULL, ARRAY['https://www.worldsnowboardfederation.org/world-rookie-snowboard-finals-2025-2/']::text[], 'likely'),
  ('world-rookie-tour--2015', 'world-rookie-tour--2015', '2014/15 World Rookie Tour season', 'world-rookie-tour', 2015, '2014-08', '2015-04', 'contest', 'Eleven-stop season: South America Rookie Fest, Valle Nevado, Chile (Aug 2014); Australian Rookie Fest, Thredbo (Aug 2014); Iceripper Rookie Fest, Laax (Jan 2015); WSF World Rookie Fest, Livigno (Jan 2015); Bulgarian Rookie Fest, Pamporovo (Jan-Feb 2015); Transilvania Rookie Fest, Arena Platos, Romania (Feb 2015); Hellas Rookie Fest, Greece (Feb 2015); Trentino Rookie Fest, Monte Bondone (Feb-Mar 2015); Oslo Rookie Fest, Oslo Vinterpark (Feb-Mar 2015); Indy Park Rookie Fest, Nekoma, Japan (Mar 2015); and the 3Star Völkl World Rookie Finals, Ischgl (Apr 2015). Rookies were riders born 1997-1999, Groms 2000 and later. Events counted towards the TTR World Snowboard Tour.', 'verified', 'held', NULL, 'month', NULL, NULL, 'multiple', ARRAY['slopestyle','halfpipe']::text[], ARRAY['https://www.worldrookietour.com/the-tour/']::text[], 'verified'),
  ('world-rookie-tour--2024', 'world-rookie-tour--2024', 'Livigno World Rookie Fest 2024 (19th edition)', 'world-rookie-tour', 2024, '2024-01-14', '2024-01-16', 'contest', 'Recorded here as a stop rather than a full season row. Presentation Sunday 14 January, rail jam at the Snowpark20 city park in central Livigno on the Monday afternoon, finals at Mottolino Snowpark on Tuesday 16 January. Described as the nineteenth edition, which implies a first edition in 2006.', 'verified', 'held', NULL, 'day', 'Mottolino Snowpark and Snowpark20', 'Livigno', 'Italy', ARRAY['slopestyle','rail-jam']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-new-snowboard-generation-shines-at-livigno-world-rookie-fest-2024/']::text[], 'verified'),
  ('world-ski-snowboard-festival--1996', 'world-ski-snowboard-festival--1996', '1996 World Ski & Snowboard Festival (inaugural)', 'world-ski-snowboard-festival', 1996, '1996-04', '1996-04', 'contest', 'Inaugural festival, directed by Doug Perry. Ten days, 22 competitions, about 1,500 athletes. Consolidated existing spring events including the WestBeach Classic, the Whistler Cup and the Couloir Ski Race Extreme, and added a snowboard museum exhibit and around a dozen bands. First joint marketing initiative between the two rival mountains and the Whistler Resort Association.', 'verified', 'held', NULL, 'month', 'Whistler Village, Whistler Mountain and Blackcomb Mountain', 'Whistler', 'Canada', ARRAY['big-air','halfpipe','other']::text[], ARRAY['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/','http://www.watermarkinc.ca/twssfmedia/timecapsule/backgrounder.html','https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'verified'),
  ('world-ski-snowboard-festival--1997', 'world-ski-snowboard-festival--1997', '1997 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 1997, '1997-04-04', '1997-04-13', 'contest', 'Over 2,000 athletes. More than 8,000 spectators at the WestBeach Invitational Big Air at the base of Whistler Mountain. Added the Moving Pictures film festival, the Backbone Enduro Vertical Challenge and the all-night ''Heaven'' event in the Conference Centre ballroom. Record April skier numbers on both mountains.', 'verified', 'held', NULL, 'day', 'Whistler Village, Whistler Mountain and Blackcomb Mountain', 'Whistler', 'Canada', ARRAY['big-air','halfpipe','other']::text[], ARRAY['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/']::text[], 'verified'),
  ('world-ski-snowboard-festival--2015', 'world-ski-snowboard-festival--2015', '2015 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2015, '2015-04-10', '2015-04-19', 'contest', 'Programme included the Bud Light Freeride Club Series, the 72-Hour Filmmaker Showdown, the outdoor concert series and the photography competition. The Showcase Showdown pro men''s winner earned a start in the festival''s Monster Energy Shred Show.', 'verified', 'held', NULL, 'day', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', ARRAY['freeride','other']::text[], ARRAY['https://www.straight.com/life/402596/showcase-showdown-and-whistler-ski-and-snowboard-fest-go-far-beyond-rock-n-snow','https://snowboardmag.com/news/whistler-blackcombs-18th-annual-showcase-showdown-returns-march-14']::text[], 'verified'),
  ('world-ski-snowboard-festival--2018', 'world-ski-snowboard-festival--2018', '2018 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2018, '2018-04-10', '2018-04-15', 'contest', 'First edition after Vail Resorts'' acquisition, shortened to six days. The Saudan Couloir Ski Race Extreme returned after a 20-year break.', 'unverified', 'held', NULL, 'day', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', ARRAY['other']::text[], ARRAY['https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'likely'),
  ('world-ski-snowboard-festival--2019', 'world-ski-snowboard-festival--2019', '2019 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2019, '2019-04-10', '2019-04-14', 'contest', 'Shortened again to five days.', 'unverified', 'held', NULL, 'day', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', ARRAY['other']::text[], ARRAY['https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'likely'),
  ('world-ski-snowboard-festival--2020', 'world-ski-snowboard-festival--2020', '2020 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2020, '2020', NULL, 'contest', NULL, 'unverified', 'cancelled', 'Cancelled due to COVID-19.', 'year', 'Whistler Blackcomb', 'Whistler', 'Canada', NULL, ARRAY['https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'likely'),
  ('world-ski-snowboard-festival--2021', 'world-ski-snowboard-festival--2021', '2021 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2021, '2021', NULL, 'contest', NULL, 'unverified', 'cancelled', 'Cancelled due to COVID-19.', 'year', 'Whistler Blackcomb', 'Whistler', 'Canada', NULL, ARRAY['https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'likely'),
  ('world-ski-snowboard-festival--2022', 'world-ski-snowboard-festival--2022', '2022 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2022, '2022', NULL, 'contest', 'Returned after two cancelled years in a scaled-down weekend format under Gibbons Whistler ownership. Exact dates not sourced.', 'unverified', 'held', NULL, 'year', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', NULL, ARRAY['https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[], 'likely'),
  ('world-ski-snowboard-festival--2025', 'world-ski-snowboard-festival--2025', '2025 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2025, '2025', NULL, 'contest', 'Whistler Blackcomb''s own 60th anniversary timeline calls 2025 the festival''s 30th anniversary; wssf.com calls 2026 the 30-year anniversary. Dates not sourced.', 'unverified', 'held', NULL, 'year', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', NULL, ARRAY['https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx']::text[], 'likely'),
  ('world-ski-snowboard-festival--2026', 'world-ski-snowboard-festival--2026', '2026 World Ski & Snowboard Festival', 'world-ski-snowboard-festival', 2026, '2026-04-06', '2026-04-12', 'contest', 'Billed by the organisers as the 30-year anniversary. Snow programme included The Pipe (invited-rider mini pipe session), The Grind ski and snowboard rail jam series, Safety Shred Days, the Powder Puck Classic and the Slush Cup at Glacier Creek; plus Intersection and the 72-Hour Filmmaker Showdown.', 'verified', 'held', NULL, 'day', 'Whistler Blackcomb and Whistler Village', 'Whistler', 'Canada', ARRAY['halfpipe','rail-jam','other']::text[], ARRAY['https://wssf.com/','https://www.whistler.com/events/world-ski-snowboard-festival/']::text[], 'verified'),
  ('world-snowboarding-championship-whistler--2001', 'world-snowboarding-championship-whistler--2001', '2001 World Snowboarding Championships', 'world-snowboarding-championship-whistler', 2001, '2001-04-19', '2001-04-22', 'contest', 'Slopestyle, jib jam and superpipe. Pique''s year-in-review reported that American riders took most of the wins. Sponsored by WestBeach Sports, which cancelled its own WestBeach Classic to fund it.', 'verified', 'held', NULL, 'day', 'Whistler Blackcomb', 'Whistler', 'Canada', ARRAY['slopestyle','jib','superpipe']::text[], ARRAY['https://www.piquenewsmagazine.com/local-sports/whistler-the-year-in-sports-2461092','https://www.piquenewsmagazine.com/local-sports/westbeach-classic-not-on-2459602']::text[], 'verified'),
  ('world-snowboarding-championships--2012', 'world-snowboarding-championships--2012', '2012 World Snowboarding Championships', 'world-snowboarding-championships', 2012, '2012-02-10', '2012-02-19', 'contest', 'Organised by Snowboard-VM 2012 AS, owned by The Arctic Challenge, the Norwegian Snowboard Federation and Oslo Vinterpark. Described as the first world championships run by snowboarders since 1999. The Arctic Challenge did not run under its own name in 2012 as far as the sources I opened show.', 'verified', 'held', NULL, 'day', NULL, 'Oslo', 'Norway', ARRAY['slopestyle','halfpipe']::text[], ARRAY['https://en.wikipedia.org/wiki/2012_World_Snowboarding_Championships','https://www.worldsnowboardfederation.org/ttr-world-snowboarding-championships-2012-highlights/']::text[], 'verified'),
  ('world-snowboarding-championships--2016', 'world-snowboarding-championships--2016', 'The World Championships of Snowboarding 2016', 'world-snowboarding-championships', 2016, '2016-03-08', '2016-03-16', 'contest', '400 athlete spots across the three disciplines, allocated through national snowboard association quotas. Billed as the pinnacle event of the 2016 tour, and the meeting at which the TTR tour champions were crowned.', 'verified', 'held', NULL, 'day', 'Yabuli', 'Yabuli, Heilongjiang', 'China', ARRAY['halfpipe','slopestyle','big-air']::text[], ARRAY['https://www.worldsnowboardfederation.org/the-world-championships-of-snowboarding-2016-2/']::text[], 'verified'),
  ('world-snowboarding-championships-sims--1983', 'world-snowboarding-championships-sims--1983', '1983 World Snowboarding Championships', 'world-snowboarding-championships-sims', 1983, '1983', NULL, 'contest', 'The first snowboard halfpipe contest. Organised by Tom Sims with Mike Chantry; the pipe was pushed up with a snowcat and then dug out by hand. Riders on Jake Burton''s East Coast team objected to counting halfpipe in the overall standings and reportedly threatened a boycott. No exact date found in any source opened; Sims'' USPTO service-mark registration claims first use in commerce on 15 February 1983, which is the closest thing to a contemporaneous date. CONFLICT: a 2014 Snowboard Magazine piece on the Sims Retro World Championships refers to ''the 1982 2nd World Snowboard Championships in Soda Springs'', implying a 1981 or 1982 first edition; every other source opened calls 1983 the inaugural year.', 'unverified', 'held', NULL, 'year', 'Soda Springs Ski Bowl', 'Soda Springs', 'USA', ARRAY['halfpipe','slalom','downhill']::text[], ARRAY['https://www.snowboarder.com/transworld-snowboarding-archive/a-complete-history-of-the-snowboard-halfpipe','https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/news/super-pipe-dreams-halfpipe-has-come-long-way-since-a-ditch-in-tahoe-city-in-the-70s/','https://www.sierrasun.com/sports/soda-springs-goes-retro-for-tom-sims/','https://trademarks.justia.com/736/70/world-snowboarding-championships-73670866.html','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[], 'likely'),
  ('world-snowboarding-championships-sims--1984', 'world-snowboarding-championships-sims--1984', '1984 World Snowboarding Championships', 'world-snowboarding-championships-sims', 1984, '1984', NULL, 'contest', 'Tahoe Quarterly states Terry Kidwell won the halfpipe at Soda Springs in 1984 and 1985; the Sierra Sun halfpipe history says Kidwell ''won the following two years'' after Eddie Hargraves'' 1983 win. No date, no full podium and no other disciplines confirmed.', 'unverified', 'held', NULL, 'year', 'Soda Springs Ski Bowl', 'Soda Springs', 'USA', ARRAY['halfpipe']::text[], ARRAY['https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/news/super-pipe-dreams-halfpipe-has-come-long-way-since-a-ditch-in-tahoe-city-in-the-70s/']::text[], 'likely'),
  ('world-snowboarding-championships-sims--1985', 'world-snowboarding-championships-sims--1985', '1985 World Snowboarding Championships', 'world-snowboarding-championships-sims', 1985, '1985', NULL, 'contest', 'Second of Terry Kidwell''s two Soda Springs halfpipe wins per Tahoe Quarterly. Note that Breckenridge''s own history page claims Breckenridge ''hosts the first snowboard World Cup'' in 1985 - a different event from this championship, and itself disputed (see open questions).', 'unverified', 'held', NULL, 'year', 'Soda Springs Ski Bowl', 'Soda Springs', 'USA', ARRAY['halfpipe']::text[], ARRAY['https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/news/super-pipe-dreams-halfpipe-has-come-long-way-since-a-ditch-in-tahoe-city-in-the-70s/']::text[], 'likely'),
  ('world-snowboarding-championships-sims--1987', 'world-snowboarding-championships-sims--1987', '1987 World Snowboarding Championships', 'world-snowboarding-championships-sims', 1987, '1987', NULL, 'contest', 'DATE CONFLICT. The Snowboarder/TransWorld 1980s timeline and Paul Alden''s obituaries put the second Breckenridge Worlds in March 1987 - specifically, NASBA was formed on 8 March 1987, ''the day after'' the championships ended, which implies the event finished 7 March 1987. TransWorld''s halfpipe history instead dates the 1987 Breckenridge World Championships to 2-5 April 1987 and calls its pipe (about 200 feet long with near-vertical six-foot walls) the best in snowboarding to that point. Dates left null. Jose Fernandes is reported to have won the giant slalom on an asymmetrical board (snowboarding8090.com) - not corroborated, no result row written. Craig Kelly''s published timeline lists ''Swatch World Championships'' results for 1987 and 1988, which is the strongest indication that the Breckenridge Worlds carried Swatch''s name.', 'unverified', 'held', NULL, 'year', 'Breckenridge Ski Resort', 'Breckenridge', 'USA', ARRAY['halfpipe','giant-slalom','slalom']::text[], ARRAY['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://www.tetonvalleynews.net/townnews/sport/a-founding-figure-of-organized-competitive-snowboarding-has-passed/article_db455d7f-ed68-46f1-a971-050e55e36410.amp.html','https://www.snowboarder.com/transworld-snowboarding-archive/a-complete-history-of-the-snowboard-halfpipe','https://snowboarding8090.com/history/','https://www.snowboarder.com/transworld-snowboarding-archive/three-decades-transworld-snowboarding-part-1-1987-1996']::text[], 'likely'),
  ('wsf-south-america-tour--2012', 'wsf-south-america-tour--2012', 'WSF South America Tour 2012', 'wsf-south-america-tour', 2012, '2012-07-07', '2012-10-26', 'contest', 'Seven stops: Urban Rail Jam, Parque Arauco, Santiago, Chile (7 Jul); Roxy Snow Jam, Valle Nevado (8 Aug); Columbia Slopestyle, Valle Nevado (11 Aug); Mall Sport South America Rookie Fest, Valle Nevado (26 Aug); Rip Curl The Gump Big Air Show, Valle Nevado (August, exact date not given); Rey del Park, El Colorado (2 Sep); and a 2-Star indoor slopestyle grand finale in Rio de Janeiro, Brazil (24-26 Oct). Counted for TTR and WSF ranking lists.', 'verified', 'held', NULL, 'day', NULL, NULL, 'multiple', ARRAY['rail-jam','slopestyle','big-air']::text[], ARRAY['https://www.worldsnowboardfederation.org/winter-season-in-chile/']::text[], 'verified'),
  ('x-games-norway--2016', 'x-games-norway--2016', 'X Games Oslo 2016', 'x-games-norway', 2016, '2016-02-24', '2016-02-28', 'contest', 'First X Games to stage summer and winter disciplines in the same city; skateboard street ran at the Skur 13 warehouse at Filipstad Harbour. Announcement coverage places snowboard superpipe at Oslo Winter Park on 26 February and snowboard/ski big air at Toyen on 27 February. First X Games to include women''s ski and snowboard big air.', 'verified', 'held', NULL, 'day', 'Oslo Winter Park (snowboard superpipe) and Toyen (big air)', 'Oslo', 'Norway', ARRAY['superpipe','big-air']::text[], ARRAY['http://www.labelnetworks.com/x-games-oslo-to-launch-in-february-2016-bringing-together-both-summer-and-winter-sports/','https://www.firsttracksonline.com/2015/11/09/x-games-expands-to-oslo/','https://whitelines.com/snowboard-culture/snowboard-events/x-games-oslo-2016-halfpipe-finals-results-photos.html','https://www.downdays.eu/events/behind-the-scenes/a-brief-history-of-the-x-games-in-europe/']::text[], 'verified'),
  ('x-games-norway--2017', 'x-games-norway--2017', 'X Games Norway 2017 (Hafjell)', 'x-games-norway', 2017, '2017-03-08', '2017-03-11', 'contest', 'Men''s and women''s snowboard slopestyle and big air. Hafjell Resort reports 17,500 spectators and Norwegian athletes taking 3 gold, 2 silver and 1 bronze of 8 golds. No superpipe.', 'verified', 'held', NULL, 'day', 'Hafjell Alpinsenter', 'Oyer', 'Norway', ARRAY['slopestyle','big-air']::text[], ARRAY['https://de.wikipedia.org/wiki/X-Games_Norway_2017','https://www.hafjellresort.no/en/x-games']::text[], 'verified'),
  ('x-games-norway--2018', 'x-games-norway--2018', 'X Games Norway 2018 (Oslo)', 'x-games-norway', 2018, '2018-05-16', '2018-05-20', 'contest', 'Indoor/urban big air edition held in May. Dates are taken from the title of an ESPN Press Room release (''SAVE THE DATE: X Games Norway 2018 May 16-20 in Oslo''); espnpressroom.com returned HTTP 403 to this researcher so the body of the release was not read. Venue attribution to Telenor Arena is inferred from the 2019 edition and is NOT confirmed - treat as unverified.', 'unverified', 'held', NULL, 'day', 'Telenor Arena, Fornebu', 'Oslo', 'Norway', ARRAY['big-air']::text[], ARRAY['https://espnpressroom.com/us/press-releases/2018/01/save-date-x-games-norway-2018-may-16-20-oslo/','https://espnpressroom.com/us/press-releases/2018/05/x-games-norway-2018-day-two-news-and-results-rookies-dominate-the-ski-and-snowboard-big-air-competitions/']::text[], 'likely'),
  ('x-games-norway--2019', 'x-games-norway--2019', 'X Games Norway 2019 (Oslo)', 'x-games-norway', 2019, '2019-08-31', NULL, 'contest', 'Indoor edition combining winter and summer disciplines under one roof: men''s and women''s snowboard and ski big air, skateboard street, and Moto X. Only 31 August 2019 was confirmed as a competition date; the event ran over more than one day and the full date range was not established.', 'unverified', 'held', NULL, 'day', 'Telenor Arena, Fornebu', 'Oslo', 'Norway', ARRAY['big-air']::text[], ARRAY['https://radseason.com/event/x-games-norway-fornebu-norway/','https://espnpressroom.com/us/press-releases/2019/08/x-games-norway-2019-news-and-results-ski-and-snowboard-big-air-skateboard-street-and-moto-x-best-trick-best-whip-and-quarterpipe-high-air/']::text[], 'likely'),
  ('x-games-norway--2020', 'x-games-norway--2020', 'X Games Norway 2020 (Hafjell)', 'x-games-norway', 2020, '2020-03-07', '2020-03-08', 'contest', 'Big air on the Saturday, slopestyle on the Sunday, including a Knuckle Huck (recorded as ''other''). Final X Games Norway edition. Mark McMorris took his 19th career X Games medal with gold in snowboard big air here, passing Shaun White''s winter medal record.', 'verified', 'held', NULL, 'day', 'Hafjell Alpinsenter', 'Oyer', 'Norway', ARRAY['big-air','slopestyle','other']::text[], ARRAY['https://www.hafjellresort.no/en/x-games','https://espnpressroom.com/us/press-releases/2020/03/x-games-norway-2020-day-two-news-and-results/','https://en.wikipedia.org/wiki/X_Games']::text[], 'verified'),
  ('x-trail-jam--2001-a', 'x-trail-jam--2001-a', 'X-Trail Jam, January 2001', 'x-trail-jam', 2001, '2001-01', NULL, 'contest', 'Launch edition. Wikipedia''s results table lists two 2001 events, January and December, so the contest ran twice in the calendar year as it shifted to a December slot.', 'verified', 'held', NULL, 'month', 'Tokyo Dome', 'Tokyo', 'Japan', ARRAY['quarterpipe','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/X-Trail_Jam']::text[], 'verified'),
  ('x-trail-jam--2001-b', 'x-trail-jam--2001-b', 'X-Trail Jam, December 2001', 'x-trail-jam', 2001, '2001-12', NULL, 'contest', 'Second event of the 2001 calendar year; belongs to the 2001/02 season.', 'verified', 'held', NULL, 'month', 'Tokyo Dome', 'Tokyo', 'Japan', ARRAY['quarterpipe','big-air']::text[], ARRAY['https://en.wikipedia.org/wiki/X-Trail_Jam']::text[], 'verified'),
